INSERT INTO courts(court_id,name,level,region) VALUES ('court_wh_wuchang','武汉市武昌区人民法院','基层法院','湖北省武汉市武昌区');
INSERT INTO courts(court_id,name,level,region) VALUES ('court_wh_hongshan','武汉市洪山区人民法院','基层法院','湖北省武汉市洪山区');
INSERT INTO courts(court_id,name,level,region) VALUES ('court_wh_jiangan','武汉市江岸区人民法院','基层法院','湖北省武汉市江岸区');
INSERT INTO courts(court_id,name,level,region) VALUES ('court_wh_intermediate','武汉市中级人民法院','中级法院','湖北省武汉市');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_civil_lease','中华人民共和国民法典租赁合同相关条文','民法典租赁','全国人民代表大会','2021-01-01','现行有效','整理租赁期限、交付、维修、押金和违约责任的通用规则。');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_access_env','中华人民共和国无障碍环境建设法相关资料','无障碍环境建设法','全国人民代表大会常务委员会','2023-09-01','现行有效','整理无障碍设施建设、维护管理和信息交流方面的基本规定。');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_privacy_rent','中华人民共和国个人信息保护法租房场景资料','个人信息保护法','全国人民代表大会常务委员会','2021-11-01','现行有效','说明租房核验身份证件、学生身份和联系方式时的最小必要原则。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_lease_delivery','stat_civil_lease','租赁交付与约定',1,'交付状态','出租人应按约定交付房屋；设施现状、门宽测量和附属设备宜在交接清单中书面记录。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_lease_repair','stat_civil_lease','维修义务',2,'维修责任','租赁物需要维修时，双方应依法律和合同约定确定通知、期限、费用及替代安排。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_lease_fee','stat_civil_lease','费用与押金',3,'费用说明','租金、押金、中介服务费、清洁费和其他收费项目应明确约定，口头承诺不宜替代书面条款。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_access_maintain','stat_access_env','设施维护',1,'无障碍设施维护','坡道、电梯、无障碍通道等设施应保持正常使用，不得被车辆或杂物长期占用。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_access_info','stat_access_env','信息提供',2,'无障碍信息','管理人提供入口、坡度、门宽和电梯运行信息时，应尽量准确、及时并便于核验。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_privacy_min','stat_privacy_rent','最小必要',1,'个人信息最小处理','核验租赁资格时应限定信息范围、处理目的和保存期限，不应提前索取与交易无关的敏感材料。');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e9d9aef4','（2023）鄂0106民初3454号','珞桂公寓押金返还合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-11-04','承租人沈某、出租人唐某','珞桂公寓押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约11006元。','承租人沈入住珞桂公寓后主张出租人以深度保洁为由扣留押金，珞桂公寓交接过程中，承租人在发现问题后及时发送书面通知，双方遂对通知时间和费用范围产生分歧。','法院针对珞桂公寓审查了转账记录和交接照片，这些材料能够证明交易经过，结合双方履行顺序，可认定正常使用痕迹不能当然认定为损坏，未被其他证据支持的口头说法不作为主要依据。','珞桂公寓案确认：正常使用痕迹不能当然认定为损坏，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就珞桂公寓争议，法院判令返还未证明损失部分的押金，凭证支持的金额核定为8705元，其余请求分别处理。','驳回','武汉,租赁,押金返还,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ed439bcd','（2025）鄂01民初16429号','珞桂家园维修责任合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-06-28','承租人林某、出租人罗某','珞桂家园维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约1929元。','珞桂家园的租赁关系建立后出现“卫生间渗水后双方对维修期限产生分歧”问题，房屋交接表未记载争议项目，承租人与出租人随后就书面附件和实际损失各自举证。','审理珞桂家园维修责任争议时，合议庭先核对报修工单和现场检测报告，再比对合同附件和通知记录，根据现有证据，出租人知悉后未及时维修应承担相应责任，责任应按实际影响划分。','裁判要点是出租人知悉后未及时维修应承担相应责任，在珞桂家园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','珞桂家园维修责任事项最终按“承担维修费并赔偿合理损失”执行，经核算，支持金额为1653元，超出证据范围的部分不予支持。','驳回','武汉,租赁,维修责任,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_b0756797','（2024）鄂0102民初21389号','珞桂里巷门宽说明合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2024-08-27','承租人周某、出租人许某','珞桂里巷门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约7877元。','围绕珞桂里巷房屋，双方确认发生过中介口头承诺入口门宽但交付时测量不符，由于房屋交接表未记载争议项目，押金、维修或服务费用的承担方式未能协商一致。','珞桂里巷案卷中的聊天记录和门宽测量照片与时间记录可以相互印证，法院据此认为关键居住条件构成订约基础时应如实说明，并对双方未写入合同的承诺从严审查。','法院在珞桂里巷案件中明确关键居住条件构成订约基础时应如实说明，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对珞桂里巷作出处理：退还服务费并调整违约责任，已查明损失按981元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,门宽说明,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8a905691','（2024）鄂0111民初18621号','珞桂社区电梯停运合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-09-21','承租人顾某、出租人韩某','珞桂社区电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约14778元。','本案源于珞桂社区交付后的电梯停运事项，承租人提交材料称高层住宅电梯长期停运影响正常使用，出租人则以“承租人在发现问题后及时发送书面通知”解释其处理过程。','对于珞桂社区发生的电梯停运问题，法院以物业公告和维保记录为核心判断材料，综合交付状态和后续补救情况，持续停运达到影响居住程度时可酌情减租。','珞桂社区案确认：持续停运达到影响居住程度时可酌情减租，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就珞桂社区争议，法院判令按影响期间减免部分租金，凭证支持的金额核定为1993元，其余请求分别处理。','支持','武汉,租赁,电梯停运,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_0f2beb37','（2024）鄂0106民初26319号','珞桂新苑通道占用合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-04-23','承租人陈某、出租人吴某','珞桂新苑通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约16582元。','承租人陈入住珞桂新苑后主张公共坡道被电动车和杂物反复占用，珞桂新苑交接过程中，出租人提交了维修报价和付款凭证，双方遂对通知时间和费用范围产生分歧。','法院针对珞桂新苑审查了现场视频和物业投诉记录，这些材料能够证明交易经过，结合双方履行顺序，可认定管理方接报后应采取合理清理措施，未被其他证据支持的口头说法不作为主要依据。','裁判要点是管理方接报后应采取合理清理措施，在珞桂新苑租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','珞桂新苑通道占用事项最终按“限期清理并完善巡查”执行，经核算，支持金额为10851元，超出证据范围的部分不予支持。','调解','武汉,租赁,通道占用,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_179ad4e7','（2025）鄂01民初29540号','珞桂华庭中介服务费合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-04-11','承租人唐某、出租人蒋某','珞桂华庭中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约2295元。','珞桂华庭的租赁关系建立后出现“签约未成后中介收取全部服务费”问题，承租人在发现问题后及时发送书面通知，承租人与出租人随后就书面附件和实际损失各自举证。','审理珞桂华庭中介服务费争议时，合议庭先核对服务协议和带看记录，再比对合同附件和通知记录，根据现有证据，服务未完整履行时应结合实际工作量确定费用，责任应按实际影响划分。','法院在珞桂华庭案件中明确服务未完整履行时应结合实际工作量确定费用，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对珞桂华庭作出处理：退还未实际发生的服务费，已查明损失按1578元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,中介服务费,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_bc48685b','（2023）鄂0102民初11614号','珞桂街区提前退租合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-10-21','承租人罗某、出租人叶某','珞桂街区提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约4657元。','围绕珞桂街区房屋，双方确认发生过承租人因居住条件变化要求提前解除，由于房屋交接表未记载争议项目，押金、维修或服务费用的承担方式未能协商一致。','珞桂街区案卷中的合同附件和沟通邮件与时间记录可以相互印证，法院据此认为违约金过高且损失有限时可依法调整，并对双方未写入合同的承诺从严审查。','珞桂街区案确认：违约金过高且损失有限时可依法调整，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就珞桂街区争议，法院判令按实际损失承担适当责任，凭证支持的金额核定为1154元，其余请求分别处理。','调解','武汉,租赁,提前退租,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_fc9d219b','（2024）鄂0111民初4353号','珞桂邻里身份材料合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-09-13','承租人许某、出租人沈某','珞桂邻里身份材料纠纷：中介在签约前索取过多证件照片，争议金额约28994元。','本案源于珞桂邻里交付后的身份材料事项，承租人提交材料称中介在签约前索取过多证件照片，出租人则以“双方曾通过物业协调但未达成一致”解释其处理过程。','对于珞桂邻里发生的身份材料问题，法院以信息收集页面和聊天记录为核心判断材料，综合交付状态和后续补救情况，租赁核验应遵循目的明确和最小必要原则。','裁判要点是租赁核验应遵循目的明确和最小必要原则，在珞桂邻里租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','珞桂邻里身份材料事项最终按“删除无关材料并停止继续处理”执行，经核算，支持金额为14331元，超出证据范围的部分不予支持。','支持','武汉,租赁,身份材料,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_02564ec5','（2025）鄂0106民初5461号','珞桂小院书面附件合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-10-03','承租人韩某、出租人林某','珞桂小院书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约18410元。','承租人韩入住珞桂小院后主张双方对坡道维修和清洁费口头承诺发生争议，珞桂小院交接过程中，房屋交接表未记载争议项目，双方遂对通知时间和费用范围产生分歧。','法院针对珞桂小院审查了合同草案和录音摘要，这些材料能够证明交易经过，结合双方履行顺序，可认定能够写入附件的关键事项应以书面约定为主要依据，未被其他证据支持的口头说法不作为主要依据。','法院在珞桂小院案件中明确能够写入附件的关键事项应以书面约定为主要依据，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对珞桂小院作出处理：依有效书面条款确定责任，已查明损失按1884元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,书面附件,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_88cb9f69','（2024）鄂01民初21737号','珞桂住区噪音减租合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-03-08','承租人吴某、出租人周某','珞桂住区噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约28271元。','珞桂住区的租赁关系建立后出现“长期施工噪音超过合理生活容忍范围”问题，承租人在发现问题后及时发送书面通知，承租人与出租人随后就书面附件和实际损失各自举证。','审理珞桂住区噪音减租争议时，合议庭先核对施工通知和连续录音记录，再比对合同附件和通知记录，根据现有证据，出租人明知重大影响仍未披露时应承担责任，责任应按实际影响划分。','珞桂住区案确认：出租人明知重大影响仍未披露时应承担责任，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就珞桂住区争议，法院判令酌情减免受影响期间租金，凭证支持的金额核定为22753元，其余请求分别处理。','驳回','武汉,租赁,噪音减租,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_d9fad70d','（2023）鄂0102民初8455号','珞桂宿舍押金返还合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-10-25','承租人蒋某、出租人顾某','珞桂宿舍押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约24835元。','围绕珞桂宿舍房屋，双方确认发生过出租人以深度保洁为由扣留押金，由于承租人在发现问题后及时发送书面通知，押金、维修或服务费用的承担方式未能协商一致。','珞桂宿舍案卷中的转账记录和交接照片与时间记录可以相互印证，法院据此认为正常使用痕迹不能当然认定为损坏，并对双方未写入合同的承诺从严审查。','裁判要点是正常使用痕迹不能当然认定为损坏，在珞桂宿舍租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','珞桂宿舍押金返还事项最终按“返还未证明损失部分的押金”执行，经核算，支持金额为5042元，超出证据范围的部分不予支持。','调解','武汉,租赁,押金返还,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_6f06de5b','（2025）鄂0111民初28303号','珞桂雅庭维修责任合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-02-18','承租人叶某、出租人陈某','珞桂雅庭维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约10733元。','本案源于珞桂雅庭交付后的维修责任事项，承租人提交材料称卫生间渗水后双方对维修期限产生分歧，出租人则以“承租人在发现问题后及时发送书面通知”解释其处理过程。','对于珞桂雅庭发生的维修责任问题，法院以报修工单和现场检测报告为核心判断材料，综合交付状态和后续补救情况，出租人知悉后未及时维修应承担相应责任。','法院在珞桂雅庭案件中明确出租人知悉后未及时维修应承担相应责任，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对珞桂雅庭作出处理：承担维修费并赔偿合理损失，已查明损失按8857元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,维修责任,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1f884956','（2023）鄂0106民初4235号','珞桂春晓门宽说明合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-08-01','承租人沈某、出租人唐某','珞桂春晓门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约3356元。','承租人沈入住珞桂春晓后主张中介口头承诺入口门宽但交付时测量不符，珞桂春晓交接过程中，出租人提交了维修报价和付款凭证，双方遂对通知时间和费用范围产生分歧。','法院针对珞桂春晓审查了聊天记录和门宽测量照片，这些材料能够证明交易经过，结合双方履行顺序，可认定关键居住条件构成订约基础时应如实说明，未被其他证据支持的口头说法不作为主要依据。','珞桂春晓案确认：关键居住条件构成订约基础时应如实说明，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就珞桂春晓争议，法院判令退还服务费并调整违约责任，凭证支持的金额核定为2606元，其余请求分别处理。','支持','武汉,租赁,门宽说明,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e46e4876','（2025）鄂01民初5962号','珞桂和园电梯停运合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-02-24','承租人林某、出租人罗某','珞桂和园电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约13199元。','珞桂和园的租赁关系建立后出现“高层住宅电梯长期停运影响正常使用”问题，出租人提交了维修报价和付款凭证，承租人与出租人随后就书面附件和实际损失各自举证。','审理珞桂和园电梯停运争议时，合议庭先核对物业公告和维保记录，再比对合同附件和通知记录，根据现有证据，持续停运达到影响居住程度时可酌情减租，责任应按实际影响划分。','裁判要点是持续停运达到影响居住程度时可酌情减租，在珞桂和园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','珞桂和园电梯停运事项最终按“按影响期间减免部分租金”执行，经核算，支持金额为8800元，超出证据范围的部分不予支持。','驳回','武汉,租赁,电梯停运,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_f35609d7','（2025）鄂0102民初3437号','珞桂清庭通道占用合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2025-10-04','承租人周某、出租人许某','珞桂清庭通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约33789元。','围绕珞桂清庭房屋，双方确认发生过公共坡道被电动车和杂物反复占用，由于双方曾通过物业协调但未达成一致，押金、维修或服务费用的承担方式未能协商一致。','珞桂清庭案卷中的现场视频和物业投诉记录与时间记录可以相互印证，法院据此认为管理方接报后应采取合理清理措施，并对双方未写入合同的承诺从严审查。','法院在珞桂清庭案件中明确管理方接报后应采取合理清理措施，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对珞桂清庭作出处理：限期清理并完善巡查，已查明损失按28574元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,通道占用,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ed348413','（2025）鄂0111民初14900号','东湖公寓中介服务费合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-12-20','承租人顾某、出租人韩某','东湖公寓中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约9978元。','本案源于东湖公寓交付后的中介服务费事项，承租人提交材料称签约未成后中介收取全部服务费，出租人则以“双方曾通过物业协调但未达成一致”解释其处理过程。','对于东湖公寓发生的中介服务费问题，法院以服务协议和带看记录为核心判断材料，综合交付状态和后续补救情况，服务未完整履行时应结合实际工作量确定费用。','东湖公寓案确认：服务未完整履行时应结合实际工作量确定费用，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就东湖公寓争议，法院判令退还未实际发生的服务费，凭证支持的金额核定为5062元，其余请求分别处理。','调解','武汉,租赁,中介服务费,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_454711e4','（2023）鄂0106民初20733号','东湖家园提前退租合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-06-11','承租人陈某、出租人吴某','东湖家园提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约2120元。','承租人陈入住东湖家园后主张承租人因居住条件变化要求提前解除，东湖家园交接过程中，中介未能提供完整的服务过程记录，双方遂对通知时间和费用范围产生分歧。','法院针对东湖家园审查了合同附件和沟通邮件，这些材料能够证明交易经过，结合双方履行顺序，可认定违约金过高且损失有限时可依法调整，未被其他证据支持的口头说法不作为主要依据。','裁判要点是违约金过高且损失有限时可依法调整，在东湖家园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','东湖家园提前退租事项最终按“按实际损失承担适当责任”执行，经核算，支持金额为721元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,提前退租,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_2189524b','（2024）鄂01民初10388号','东湖里巷身份材料合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-08-18','承租人唐某、出租人蒋某','东湖里巷身份材料纠纷：中介在签约前索取过多证件照片，争议金额约8054元。','东湖里巷的租赁关系建立后出现“中介在签约前索取过多证件照片”问题，出租人提交了维修报价和付款凭证，承租人与出租人随后就书面附件和实际损失各自举证。','审理东湖里巷身份材料争议时，合议庭先核对信息收集页面和聊天记录，再比对合同附件和通知记录，根据现有证据，租赁核验应遵循目的明确和最小必要原则，责任应按实际影响划分。','法院在东湖里巷案件中明确租赁核验应遵循目的明确和最小必要原则，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对东湖里巷作出处理：删除无关材料并停止继续处理，已查明损失按2348元计入责任，其余由双方依合同继续履行。','调解','武汉,租赁,身份材料,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_6958e8e0','（2023）鄂0102民初19907号','东湖社区书面附件合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-02-15','承租人罗某、出租人叶某','东湖社区书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约5814元。','围绕东湖社区房屋，双方确认发生过双方对坡道维修和清洁费口头承诺发生争议，由于中介未能提供完整的服务过程记录，押金、维修或服务费用的承担方式未能协商一致。','东湖社区案卷中的合同草案和录音摘要与时间记录可以相互印证，法院据此认为能够写入附件的关键事项应以书面约定为主要依据，并对双方未写入合同的承诺从严审查。','东湖社区案确认：能够写入附件的关键事项应以书面约定为主要依据，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就东湖社区争议，法院判令依有效书面条款确定责任，凭证支持的金额核定为4112元，其余请求分别处理。','调解','武汉,租赁,书面附件,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_b534217f','（2024）鄂0111民初20030号','东湖新苑噪音减租合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-06-05','承租人许某、出租人沈某','东湖新苑噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约24522元。','本案源于东湖新苑交付后的噪音减租事项，承租人提交材料称长期施工噪音超过合理生活容忍范围，出租人则以“出租人提交了维修报价和付款凭证”解释其处理过程。','对于东湖新苑发生的噪音减租问题，法院以施工通知和连续录音记录为核心判断材料，综合交付状态和后续补救情况，出租人明知重大影响仍未披露时应承担责任。','裁判要点是出租人明知重大影响仍未披露时应承担责任，在东湖新苑租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','东湖新苑噪音减租事项最终按“酌情减免受影响期间租金”执行，经核算，支持金额为3825元，超出证据范围的部分不予支持。','驳回','武汉,租赁,噪音减租,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_190c8c6a','（2024）鄂0106民初14852号','东湖华庭押金返还合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-07-08','承租人韩某、出租人林某','东湖华庭押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约29560元。','承租人韩入住东湖华庭后主张出租人以深度保洁为由扣留押金，东湖华庭交接过程中，出租人提交了维修报价和付款凭证，双方遂对通知时间和费用范围产生分歧。','法院针对东湖华庭审查了转账记录和交接照片，这些材料能够证明交易经过，结合双方履行顺序，可认定正常使用痕迹不能当然认定为损坏，未被其他证据支持的口头说法不作为主要依据。','法院在东湖华庭案件中明确正常使用痕迹不能当然认定为损坏，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对东湖华庭作出处理：返还未证明损失部分的押金，已查明损失按3386元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,押金返还,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_84e4ada9','（2023）鄂01民初28854号','东湖街区维修责任合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2023-06-01','承租人吴某、出租人周某','东湖街区维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约30264元。','东湖街区的租赁关系建立后出现“卫生间渗水后双方对维修期限产生分歧”问题，中介未能提供完整的服务过程记录，承租人与出租人随后就书面附件和实际损失各自举证。','审理东湖街区维修责任争议时，合议庭先核对报修工单和现场检测报告，再比对合同附件和通知记录，根据现有证据，出租人知悉后未及时维修应承担相应责任，责任应按实际影响划分。','东湖街区案确认：出租人知悉后未及时维修应承担相应责任，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就东湖街区争议，法院判令承担维修费并赔偿合理损失，凭证支持的金额核定为23658元，其余请求分别处理。','部分支持','武汉,租赁,维修责任,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_db3e6db7','（2023）鄂0102民初1161号','东湖邻里门宽说明合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-11-15','承租人蒋某、出租人顾某','东湖邻里门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约29483元。','围绕东湖邻里房屋，双方确认发生过中介口头承诺入口门宽但交付时测量不符，由于中介未能提供完整的服务过程记录，押金、维修或服务费用的承担方式未能协商一致。','东湖邻里案卷中的聊天记录和门宽测量照片与时间记录可以相互印证，法院据此认为关键居住条件构成订约基础时应如实说明，并对双方未写入合同的承诺从严审查。','裁判要点是关键居住条件构成订约基础时应如实说明，在东湖邻里租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','东湖邻里门宽说明事项最终按“退还服务费并调整违约责任”执行，经核算，支持金额为17495元，超出证据范围的部分不予支持。','驳回','武汉,租赁,门宽说明,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_7362107e','（2023）鄂0111民初24115号','东湖小院电梯停运合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2023-02-17','承租人叶某、出租人陈某','东湖小院电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约32716元。','本案源于东湖小院交付后的电梯停运事项，承租人提交材料称高层住宅电梯长期停运影响正常使用，出租人则以“承租人在发现问题后及时发送书面通知”解释其处理过程。','对于东湖小院发生的电梯停运问题，法院以物业公告和维保记录为核心判断材料，综合交付状态和后续补救情况，持续停运达到影响居住程度时可酌情减租。','法院在东湖小院案件中明确持续停运达到影响居住程度时可酌情减租，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对东湖小院作出处理：按影响期间减免部分租金，已查明损失按30342元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,电梯停运,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_268be53b','（2025）鄂0106民初15457号','东湖住区通道占用合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-04-15','承租人沈某、出租人唐某','东湖住区通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约13289元。','承租人沈入住东湖住区后主张公共坡道被电动车和杂物反复占用，东湖住区交接过程中，双方曾通过物业协调但未达成一致，双方遂对通知时间和费用范围产生分歧。','法院针对东湖住区审查了现场视频和物业投诉记录，这些材料能够证明交易经过，结合双方履行顺序，可认定管理方接报后应采取合理清理措施，未被其他证据支持的口头说法不作为主要依据。','东湖住区案确认：管理方接报后应采取合理清理措施，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就东湖住区争议，法院判令限期清理并完善巡查，凭证支持的金额核定为6039元，其余请求分别处理。','支持','武汉,租赁,通道占用,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1d4bd7bf','（2024）鄂01民初16828号','东湖宿舍中介服务费合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-09-24','承租人林某、出租人罗某','东湖宿舍中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约10187元。','东湖宿舍的租赁关系建立后出现“签约未成后中介收取全部服务费”问题，双方曾通过物业协调但未达成一致，承租人与出租人随后就书面附件和实际损失各自举证。','审理东湖宿舍中介服务费争议时，合议庭先核对服务协议和带看记录，再比对合同附件和通知记录，根据现有证据，服务未完整履行时应结合实际工作量确定费用，责任应按实际影响划分。','裁判要点是服务未完整履行时应结合实际工作量确定费用，在东湖宿舍租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','东湖宿舍中介服务费事项最终按“退还未实际发生的服务费”执行，经核算，支持金额为2026元，超出证据范围的部分不予支持。','调解','武汉,租赁,中介服务费,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_5c44e861','（2025）鄂0102民初8521号','东湖雅庭提前退租合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2025-08-11','承租人周某、出租人许某','东湖雅庭提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约29644元。','围绕东湖雅庭房屋，双方确认发生过承租人因居住条件变化要求提前解除，由于中介未能提供完整的服务过程记录，押金、维修或服务费用的承担方式未能协商一致。','东湖雅庭案卷中的合同附件和沟通邮件与时间记录可以相互印证，法院据此认为违约金过高且损失有限时可依法调整，并对双方未写入合同的承诺从严审查。','法院在东湖雅庭案件中明确违约金过高且损失有限时可依法调整，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对东湖雅庭作出处理：按实际损失承担适当责任，已查明损失按27806元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,提前退租,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_050fc7be','（2025）鄂0111民初2472号','东湖春晓身份材料合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-04-13','承租人顾某、出租人韩某','东湖春晓身份材料纠纷：中介在签约前索取过多证件照片，争议金额约16796元。','本案源于东湖春晓交付后的身份材料事项，承租人提交材料称中介在签约前索取过多证件照片，出租人则以“双方曾通过物业协调但未达成一致”解释其处理过程。','对于东湖春晓发生的身份材料问题，法院以信息收集页面和聊天记录为核心判断材料，综合交付状态和后续补救情况，租赁核验应遵循目的明确和最小必要原则。','东湖春晓案确认：租赁核验应遵循目的明确和最小必要原则，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就东湖春晓争议，法院判令删除无关材料并停止继续处理，凭证支持的金额核定为9184元，其余请求分别处理。','部分支持','武汉,租赁,身份材料,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_b7444741','（2025）鄂0106民初3652号','东湖和园书面附件合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-06-08','承租人陈某、出租人吴某','东湖和园书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约14213元。','承租人陈入住东湖和园后主张双方对坡道维修和清洁费口头承诺发生争议，东湖和园交接过程中，中介未能提供完整的服务过程记录，双方遂对通知时间和费用范围产生分歧。','法院针对东湖和园审查了合同草案和录音摘要，这些材料能够证明交易经过，结合双方履行顺序，可认定能够写入附件的关键事项应以书面约定为主要依据，未被其他证据支持的口头说法不作为主要依据。','裁判要点是能够写入附件的关键事项应以书面约定为主要依据，在东湖和园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','东湖和园书面附件事项最终按“依有效书面条款确定责任”执行，经核算，支持金额为2038元，超出证据范围的部分不予支持。','调解','武汉,租赁,书面附件,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e092dbcb','（2023）鄂01民初28320号','东湖清庭噪音减租合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2023-09-09','承租人唐某、出租人蒋某','东湖清庭噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约18080元。','东湖清庭的租赁关系建立后出现“长期施工噪音超过合理生活容忍范围”问题，中介未能提供完整的服务过程记录，承租人与出租人随后就书面附件和实际损失各自举证。','审理东湖清庭噪音减租争议时，合议庭先核对施工通知和连续录音记录，再比对合同附件和通知记录，根据现有证据，出租人明知重大影响仍未披露时应承担责任，责任应按实际影响划分。','法院在东湖清庭案件中明确出租人明知重大影响仍未披露时应承担责任，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对东湖清庭作出处理：酌情减免受影响期间租金，已查明损失按17069元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,噪音减租,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_430b8afb','（2023）鄂0102民初8431号','南望公寓押金返还合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-06-11','承租人罗某、出租人叶某','南望公寓押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约35253元。','围绕南望公寓房屋，双方确认发生过出租人以深度保洁为由扣留押金，由于中介未能提供完整的服务过程记录，押金、维修或服务费用的承担方式未能协商一致。','南望公寓案卷中的转账记录和交接照片与时间记录可以相互印证，法院据此认为正常使用痕迹不能当然认定为损坏，并对双方未写入合同的承诺从严审查。','南望公寓案确认：正常使用痕迹不能当然认定为损坏，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就南望公寓争议，法院判令返还未证明损失部分的押金，凭证支持的金额核定为4047元，其余请求分别处理。','部分支持','武汉,租赁,押金返还,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_fb2c75cb','（2023）鄂0111民初19073号','南望家园维修责任合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2023-11-03','承租人许某、出租人沈某','南望家园维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约11417元。','本案源于南望家园交付后的维修责任事项，承租人提交材料称卫生间渗水后双方对维修期限产生分歧，出租人则以“中介未能提供完整的服务过程记录”解释其处理过程。','对于南望家园发生的维修责任问题，法院以报修工单和现场检测报告为核心判断材料，综合交付状态和后续补救情况，出租人知悉后未及时维修应承担相应责任。','裁判要点是出租人知悉后未及时维修应承担相应责任，在南望家园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','南望家园维修责任事项最终按“承担维修费并赔偿合理损失”执行，经核算，支持金额为7424元，超出证据范围的部分不予支持。','调解','武汉,租赁,维修责任,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_944fdcec','（2025）鄂0106民初12264号','南望里巷门宽说明合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-01-15','承租人韩某、出租人林某','南望里巷门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约35633元。','承租人韩入住南望里巷后主张中介口头承诺入口门宽但交付时测量不符，南望里巷交接过程中，中介未能提供完整的服务过程记录，双方遂对通知时间和费用范围产生分歧。','法院针对南望里巷审查了聊天记录和门宽测量照片，这些材料能够证明交易经过，结合双方履行顺序，可认定关键居住条件构成订约基础时应如实说明，未被其他证据支持的口头说法不作为主要依据。','法院在南望里巷案件中明确关键居住条件构成订约基础时应如实说明，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对南望里巷作出处理：退还服务费并调整违约责任，已查明损失按11652元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,门宽说明,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_7d9dd83a','（2023）鄂01民初26447号','南望社区电梯停运合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2023-10-02','承租人吴某、出租人周某','南望社区电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约20436元。','南望社区的租赁关系建立后出现“高层住宅电梯长期停运影响正常使用”问题，房屋交接表未记载争议项目，承租人与出租人随后就书面附件和实际损失各自举证。','审理南望社区电梯停运争议时，合议庭先核对物业公告和维保记录，再比对合同附件和通知记录，根据现有证据，持续停运达到影响居住程度时可酌情减租，责任应按实际影响划分。','南望社区案确认：持续停运达到影响居住程度时可酌情减租，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就南望社区争议，法院判令按影响期间减免部分租金，凭证支持的金额核定为11682元，其余请求分别处理。','驳回','武汉,租赁,电梯停运,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_276bdc67','（2025）鄂0102民初22724号','南望新苑通道占用合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2025-10-23','承租人蒋某、出租人顾某','南望新苑通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约10104元。','围绕南望新苑房屋，双方确认发生过公共坡道被电动车和杂物反复占用，由于房屋交接表未记载争议项目，押金、维修或服务费用的承担方式未能协商一致。','南望新苑案卷中的现场视频和物业投诉记录与时间记录可以相互印证，法院据此认为管理方接报后应采取合理清理措施，并对双方未写入合同的承诺从严审查。','裁判要点是管理方接报后应采取合理清理措施，在南望新苑租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','南望新苑通道占用事项最终按“限期清理并完善巡查”执行，经核算，支持金额为8076元，超出证据范围的部分不予支持。','支持','武汉,租赁,通道占用,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_fe234ded','（2025）鄂0111民初1719号','南望华庭中介服务费合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-10-28','承租人叶某、出租人陈某','南望华庭中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约1843元。','本案源于南望华庭交付后的中介服务费事项，承租人提交材料称签约未成后中介收取全部服务费，出租人则以“中介未能提供完整的服务过程记录”解释其处理过程。','对于南望华庭发生的中介服务费问题，法院以服务协议和带看记录为核心判断材料，综合交付状态和后续补救情况，服务未完整履行时应结合实际工作量确定费用。','法院在南望华庭案件中明确服务未完整履行时应结合实际工作量确定费用，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对南望华庭作出处理：退还未实际发生的服务费，已查明损失按638元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,中介服务费,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e40fe852','（2023）鄂0106民初9269号','南望街区提前退租合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-10-18','承租人沈某、出租人唐某','南望街区提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约18684元。','承租人沈入住南望街区后主张承租人因居住条件变化要求提前解除，南望街区交接过程中，出租人提交了维修报价和付款凭证，双方遂对通知时间和费用范围产生分歧。','法院针对南望街区审查了合同附件和沟通邮件，这些材料能够证明交易经过，结合双方履行顺序，可认定违约金过高且损失有限时可依法调整，未被其他证据支持的口头说法不作为主要依据。','南望街区案确认：违约金过高且损失有限时可依法调整，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就南望街区争议，法院判令按实际损失承担适当责任，凭证支持的金额核定为18562元，其余请求分别处理。','驳回','武汉,租赁,提前退租,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_17efd3e1','（2024）鄂01民初26119号','南望邻里身份材料合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-03-17','承租人林某、出租人罗某','南望邻里身份材料纠纷：中介在签约前索取过多证件照片，争议金额约26019元。','南望邻里的租赁关系建立后出现“中介在签约前索取过多证件照片”问题，出租人提交了维修报价和付款凭证，承租人与出租人随后就书面附件和实际损失各自举证。','审理南望邻里身份材料争议时，合议庭先核对信息收集页面和聊天记录，再比对合同附件和通知记录，根据现有证据，租赁核验应遵循目的明确和最小必要原则，责任应按实际影响划分。','裁判要点是租赁核验应遵循目的明确和最小必要原则，在南望邻里租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','南望邻里身份材料事项最终按“删除无关材料并停止继续处理”执行，经核算，支持金额为17961元，超出证据范围的部分不予支持。','驳回','武汉,租赁,身份材料,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_7947dab6','（2024）鄂0102民初8527号','南望小院书面附件合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2024-10-02','承租人周某、出租人许某','南望小院书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约8664元。','围绕南望小院房屋，双方确认发生过双方对坡道维修和清洁费口头承诺发生争议，由于承租人在发现问题后及时发送书面通知，押金、维修或服务费用的承担方式未能协商一致。','南望小院案卷中的合同草案和录音摘要与时间记录可以相互印证，法院据此认为能够写入附件的关键事项应以书面约定为主要依据，并对双方未写入合同的承诺从严审查。','法院在南望小院案件中明确能够写入附件的关键事项应以书面约定为主要依据，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对南望小院作出处理：依有效书面条款确定责任，已查明损失按2252元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,书面附件,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_89352bb1','（2025）鄂0111民初12718号','南望住区噪音减租合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-11-27','承租人顾某、出租人韩某','南望住区噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约21474元。','本案源于南望住区交付后的噪音减租事项，承租人提交材料称长期施工噪音超过合理生活容忍范围，出租人则以“双方曾通过物业协调但未达成一致”解释其处理过程。','对于南望住区发生的噪音减租问题，法院以施工通知和连续录音记录为核心判断材料，综合交付状态和后续补救情况，出租人明知重大影响仍未披露时应承担责任。','南望住区案确认：出租人明知重大影响仍未披露时应承担责任，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就南望住区争议，法院判令酌情减免受影响期间租金，凭证支持的金额核定为9872元，其余请求分别处理。','部分支持','武汉,租赁,噪音减租,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_d3fe480c','（2023）鄂0106民初11231号','南望宿舍押金返还合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-11-22','承租人陈某、出租人吴某','南望宿舍押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约19177元。','承租人陈入住南望宿舍后主张出租人以深度保洁为由扣留押金，南望宿舍交接过程中，房屋交接表未记载争议项目，双方遂对通知时间和费用范围产生分歧。','法院针对南望宿舍审查了转账记录和交接照片，这些材料能够证明交易经过，结合双方履行顺序，可认定正常使用痕迹不能当然认定为损坏，未被其他证据支持的口头说法不作为主要依据。','裁判要点是正常使用痕迹不能当然认定为损坏，在南望宿舍租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','南望宿舍押金返还事项最终按“返还未证明损失部分的押金”执行，经核算，支持金额为16840元，超出证据范围的部分不予支持。','支持','武汉,租赁,押金返还,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_9090bc4c','（2025）鄂01民初18907号','南望雅庭维修责任合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-03-28','承租人唐某、出租人蒋某','南望雅庭维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约35605元。','南望雅庭的租赁关系建立后出现“卫生间渗水后双方对维修期限产生分歧”问题，出租人提交了维修报价和付款凭证，承租人与出租人随后就书面附件和实际损失各自举证。','审理南望雅庭维修责任争议时，合议庭先核对报修工单和现场检测报告，再比对合同附件和通知记录，根据现有证据，出租人知悉后未及时维修应承担相应责任，责任应按实际影响划分。','法院在南望雅庭案件中明确出租人知悉后未及时维修应承担相应责任，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对南望雅庭作出处理：承担维修费并赔偿合理损失，已查明损失按1287元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,维修责任,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_99cfbfc9','（2023）鄂0102民初19107号','南望春晓门宽说明合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-11-16','承租人罗某、出租人叶某','南望春晓门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约35899元。','围绕南望春晓房屋，双方确认发生过中介口头承诺入口门宽但交付时测量不符，由于出租人提交了维修报价和付款凭证，押金、维修或服务费用的承担方式未能协商一致。','南望春晓案卷中的聊天记录和门宽测量照片与时间记录可以相互印证，法院据此认为关键居住条件构成订约基础时应如实说明，并对双方未写入合同的承诺从严审查。','南望春晓案确认：关键居住条件构成订约基础时应如实说明，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就南望春晓争议，法院判令退还服务费并调整违约责任，凭证支持的金额核定为28758元，其余请求分别处理。','部分支持','武汉,租赁,门宽说明,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_b880d57e','（2023）鄂0111民初15441号','南望和园电梯停运合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2023-01-07','承租人许某、出租人沈某','南望和园电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约4466元。','本案源于南望和园交付后的电梯停运事项，承租人提交材料称高层住宅电梯长期停运影响正常使用，出租人则以“中介未能提供完整的服务过程记录”解释其处理过程。','对于南望和园发生的电梯停运问题，法院以物业公告和维保记录为核心判断材料，综合交付状态和后续补救情况，持续停运达到影响居住程度时可酌情减租。','裁判要点是持续停运达到影响居住程度时可酌情减租，在南望和园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','南望和园电梯停运事项最终按“按影响期间减免部分租金”执行，经核算，支持金额为4226元，超出证据范围的部分不予支持。','驳回','武汉,租赁,电梯停运,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_72940c7f','（2024）鄂0106民初20111号','南望清庭通道占用合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-11-11','承租人韩某、出租人林某','南望清庭通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约11513元。','承租人韩入住南望清庭后主张公共坡道被电动车和杂物反复占用，南望清庭交接过程中，中介未能提供完整的服务过程记录，双方遂对通知时间和费用范围产生分歧。','法院针对南望清庭审查了现场视频和物业投诉记录，这些材料能够证明交易经过，结合双方履行顺序，可认定管理方接报后应采取合理清理措施，未被其他证据支持的口头说法不作为主要依据。','法院在南望清庭案件中明确管理方接报后应采取合理清理措施，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对南望清庭作出处理：限期清理并完善巡查，已查明损失按1584元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,通道占用,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1478ba49','（2024）鄂01民初7202号','楚风公寓中介服务费合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-06-22','承租人吴某、出租人周某','楚风公寓中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约21185元。','楚风公寓的租赁关系建立后出现“签约未成后中介收取全部服务费”问题，双方曾通过物业协调但未达成一致，承租人与出租人随后就书面附件和实际损失各自举证。','审理楚风公寓中介服务费争议时，合议庭先核对服务协议和带看记录，再比对合同附件和通知记录，根据现有证据，服务未完整履行时应结合实际工作量确定费用，责任应按实际影响划分。','楚风公寓案确认：服务未完整履行时应结合实际工作量确定费用，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就楚风公寓争议，法院判令退还未实际发生的服务费，凭证支持的金额核定为14251元，其余请求分别处理。','驳回','武汉,租赁,中介服务费,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_efb399cd','（2025）鄂0102民初3158号','楚风家园提前退租合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2025-07-01','承租人蒋某、出租人顾某','楚风家园提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约8640元。','围绕楚风家园房屋，双方确认发生过承租人因居住条件变化要求提前解除，由于出租人提交了维修报价和付款凭证，押金、维修或服务费用的承担方式未能协商一致。','楚风家园案卷中的合同附件和沟通邮件与时间记录可以相互印证，法院据此认为违约金过高且损失有限时可依法调整，并对双方未写入合同的承诺从严审查。','裁判要点是违约金过高且损失有限时可依法调整，在楚风家园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','楚风家园提前退租事项最终按“按实际损失承担适当责任”执行，经核算，支持金额为3499元，超出证据范围的部分不予支持。','支持','武汉,租赁,提前退租,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_f2755471','（2024）鄂0111民初1906号','楚风里巷身份材料合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-04-10','承租人叶某、出租人陈某','楚风里巷身份材料纠纷：中介在签约前索取过多证件照片，争议金额约14216元。','本案源于楚风里巷交付后的身份材料事项，承租人提交材料称中介在签约前索取过多证件照片，出租人则以“双方曾通过物业协调但未达成一致”解释其处理过程。','对于楚风里巷发生的身份材料问题，法院以信息收集页面和聊天记录为核心判断材料，综合交付状态和后续补救情况，租赁核验应遵循目的明确和最小必要原则。','法院在楚风里巷案件中明确租赁核验应遵循目的明确和最小必要原则，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对楚风里巷作出处理：删除无关材料并停止继续处理，已查明损失按3453元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,身份材料,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_dd4d518b','（2025）鄂0106民初19719号','楚风社区书面附件合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-04-23','承租人沈某、出租人唐某','楚风社区书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约28994元。','承租人沈入住楚风社区后主张双方对坡道维修和清洁费口头承诺发生争议，楚风社区交接过程中，出租人提交了维修报价和付款凭证，双方遂对通知时间和费用范围产生分歧。','法院针对楚风社区审查了合同草案和录音摘要，这些材料能够证明交易经过，结合双方履行顺序，可认定能够写入附件的关键事项应以书面约定为主要依据，未被其他证据支持的口头说法不作为主要依据。','楚风社区案确认：能够写入附件的关键事项应以书面约定为主要依据，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就楚风社区争议，法院判令依有效书面条款确定责任，凭证支持的金额核定为23699元，其余请求分别处理。','调解','武汉,租赁,书面附件,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_c0e50fbe','（2024）鄂01民初25733号','楚风新苑噪音减租合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-12-11','承租人林某、出租人罗某','楚风新苑噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约9302元。','楚风新苑的租赁关系建立后出现“长期施工噪音超过合理生活容忍范围”问题，中介未能提供完整的服务过程记录，承租人与出租人随后就书面附件和实际损失各自举证。','审理楚风新苑噪音减租争议时，合议庭先核对施工通知和连续录音记录，再比对合同附件和通知记录，根据现有证据，出租人明知重大影响仍未披露时应承担责任，责任应按实际影响划分。','裁判要点是出租人明知重大影响仍未披露时应承担责任，在楚风新苑租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','楚风新苑噪音减租事项最终按“酌情减免受影响期间租金”执行，经核算，支持金额为2888元，超出证据范围的部分不予支持。','驳回','武汉,租赁,噪音减租,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8282fc2e','（2025）鄂0102民初9285号','楚风华庭押金返还合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2025-10-12','承租人周某、出租人许某','楚风华庭押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约18436元。','围绕楚风华庭房屋，双方确认发生过出租人以深度保洁为由扣留押金，由于中介未能提供完整的服务过程记录，押金、维修或服务费用的承担方式未能协商一致。','楚风华庭案卷中的转账记录和交接照片与时间记录可以相互印证，法院据此认为正常使用痕迹不能当然认定为损坏，并对双方未写入合同的承诺从严审查。','法院在楚风华庭案件中明确正常使用痕迹不能当然认定为损坏，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对楚风华庭作出处理：返还未证明损失部分的押金，已查明损失按582元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,押金返还,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e30dc291','（2023）鄂0111民初6069号','楚风街区维修责任合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2023-08-01','承租人顾某、出租人韩某','楚风街区维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约31120元。','本案源于楚风街区交付后的维修责任事项，承租人提交材料称卫生间渗水后双方对维修期限产生分歧，出租人则以“出租人提交了维修报价和付款凭证”解释其处理过程。','对于楚风街区发生的维修责任问题，法院以报修工单和现场检测报告为核心判断材料，综合交付状态和后续补救情况，出租人知悉后未及时维修应承担相应责任。','楚风街区案确认：出租人知悉后未及时维修应承担相应责任，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就楚风街区争议，法院判令承担维修费并赔偿合理损失，凭证支持的金额核定为22938元，其余请求分别处理。','调解','武汉,租赁,维修责任,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_f8a0b9d6','（2025）鄂0106民初25825号','楚风邻里门宽说明合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-05-05','承租人陈某、出租人吴某','楚风邻里门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约6911元。','承租人陈入住楚风邻里后主张中介口头承诺入口门宽但交付时测量不符，楚风邻里交接过程中，房屋交接表未记载争议项目，双方遂对通知时间和费用范围产生分歧。','法院针对楚风邻里审查了聊天记录和门宽测量照片，这些材料能够证明交易经过，结合双方履行顺序，可认定关键居住条件构成订约基础时应如实说明，未被其他证据支持的口头说法不作为主要依据。','裁判要点是关键居住条件构成订约基础时应如实说明，在楚风邻里租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','楚风邻里门宽说明事项最终按“退还服务费并调整违约责任”执行，经核算，支持金额为442元，超出证据范围的部分不予支持。','调解','武汉,租赁,门宽说明,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_a80bcf1b','（2025）鄂01民初12249号','楚风小院电梯停运合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-11-02','承租人唐某、出租人蒋某','楚风小院电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约24445元。','楚风小院的租赁关系建立后出现“高层住宅电梯长期停运影响正常使用”问题，房屋交接表未记载争议项目，承租人与出租人随后就书面附件和实际损失各自举证。','审理楚风小院电梯停运争议时，合议庭先核对物业公告和维保记录，再比对合同附件和通知记录，根据现有证据，持续停运达到影响居住程度时可酌情减租，责任应按实际影响划分。','法院在楚风小院案件中明确持续停运达到影响居住程度时可酌情减租，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对楚风小院作出处理：按影响期间减免部分租金，已查明损失按1210元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,电梯停运,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_2bcb8546','（2024）鄂0102民初21554号','楚风住区通道占用合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2024-07-20','承租人罗某、出租人叶某','楚风住区通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约5708元。','围绕楚风住区房屋，双方确认发生过公共坡道被电动车和杂物反复占用，由于中介未能提供完整的服务过程记录，押金、维修或服务费用的承担方式未能协商一致。','楚风住区案卷中的现场视频和物业投诉记录与时间记录可以相互印证，法院据此认为管理方接报后应采取合理清理措施，并对双方未写入合同的承诺从严审查。','楚风住区案确认：管理方接报后应采取合理清理措施，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就楚风住区争议，法院判令限期清理并完善巡查，凭证支持的金额核定为3961元，其余请求分别处理。','支持','武汉,租赁,通道占用,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_fec36c83','（2024）鄂0111民初18531号','楚风宿舍中介服务费合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-01-25','承租人许某、出租人沈某','楚风宿舍中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约30232元。','本案源于楚风宿舍交付后的中介服务费事项，承租人提交材料称签约未成后中介收取全部服务费，出租人则以“双方曾通过物业协调但未达成一致”解释其处理过程。','对于楚风宿舍发生的中介服务费问题，法院以服务协议和带看记录为核心判断材料，综合交付状态和后续补救情况，服务未完整履行时应结合实际工作量确定费用。','裁判要点是服务未完整履行时应结合实际工作量确定费用，在楚风宿舍租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','楚风宿舍中介服务费事项最终按“退还未实际发生的服务费”执行，经核算，支持金额为9913元，超出证据范围的部分不予支持。','调解','武汉,租赁,中介服务费,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1630de48','（2023）鄂0106民初16726号','楚风雅庭提前退租合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-08-23','承租人韩某、出租人林某','楚风雅庭提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约6785元。','承租人韩入住楚风雅庭后主张承租人因居住条件变化要求提前解除，楚风雅庭交接过程中，中介未能提供完整的服务过程记录，双方遂对通知时间和费用范围产生分歧。','法院针对楚风雅庭审查了合同附件和沟通邮件，这些材料能够证明交易经过，结合双方履行顺序，可认定违约金过高且损失有限时可依法调整，未被其他证据支持的口头说法不作为主要依据。','法院在楚风雅庭案件中明确违约金过高且损失有限时可依法调整，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对楚风雅庭作出处理：按实际损失承担适当责任，已查明损失按2269元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,提前退租,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_627428d0','（2025）鄂01民初25099号','楚风春晓身份材料合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-01-21','承租人吴某、出租人周某','楚风春晓身份材料纠纷：中介在签约前索取过多证件照片，争议金额约11262元。','楚风春晓的租赁关系建立后出现“中介在签约前索取过多证件照片”问题，出租人提交了维修报价和付款凭证，承租人与出租人随后就书面附件和实际损失各自举证。','审理楚风春晓身份材料争议时，合议庭先核对信息收集页面和聊天记录，再比对合同附件和通知记录，根据现有证据，租赁核验应遵循目的明确和最小必要原则，责任应按实际影响划分。','楚风春晓案确认：租赁核验应遵循目的明确和最小必要原则，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就楚风春晓争议，法院判令删除无关材料并停止继续处理，凭证支持的金额核定为760元，其余请求分别处理。','支持','武汉,租赁,身份材料,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_bd771b1f','（2023）鄂0102民初25838号','楚风和园书面附件合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-09-09','承租人蒋某、出租人顾某','楚风和园书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约10754元。','围绕楚风和园房屋，双方确认发生过双方对坡道维修和清洁费口头承诺发生争议，由于房屋交接表未记载争议项目，押金、维修或服务费用的承担方式未能协商一致。','楚风和园案卷中的合同草案和录音摘要与时间记录可以相互印证，法院据此认为能够写入附件的关键事项应以书面约定为主要依据，并对双方未写入合同的承诺从严审查。','裁判要点是能够写入附件的关键事项应以书面约定为主要依据，在楚风和园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','楚风和园书面附件事项最终按“依有效书面条款确定责任”执行，经核算，支持金额为9874元，超出证据范围的部分不予支持。','支持','武汉,租赁,书面附件,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_9f74a5a9','（2025）鄂0111民初7924号','楚风清庭噪音减租合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-08-23','承租人叶某、出租人陈某','楚风清庭噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约22945元。','本案源于楚风清庭交付后的噪音减租事项，承租人提交材料称长期施工噪音超过合理生活容忍范围，出租人则以“出租人提交了维修报价和付款凭证”解释其处理过程。','对于楚风清庭发生的噪音减租问题，法院以施工通知和连续录音记录为核心判断材料，综合交付状态和后续补救情况，出租人明知重大影响仍未披露时应承担责任。','法院在楚风清庭案件中明确出租人明知重大影响仍未披露时应承担责任，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对楚风清庭作出处理：酌情减免受影响期间租金，已查明损失按19026元计入责任，其余由双方依合同继续履行。','调解','武汉,租赁,噪音减租,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_79eb9263','（2024）鄂0106民初20165号','晴川公寓押金返还合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-12-19','承租人沈某、出租人唐某','晴川公寓押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约14861元。','承租人沈入住晴川公寓后主张出租人以深度保洁为由扣留押金，晴川公寓交接过程中，出租人提交了维修报价和付款凭证，双方遂对通知时间和费用范围产生分歧。','法院针对晴川公寓审查了转账记录和交接照片，这些材料能够证明交易经过，结合双方履行顺序，可认定正常使用痕迹不能当然认定为损坏，未被其他证据支持的口头说法不作为主要依据。','晴川公寓案确认：正常使用痕迹不能当然认定为损坏，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就晴川公寓争议，法院判令返还未证明损失部分的押金，凭证支持的金额核定为7875元，其余请求分别处理。','部分支持','武汉,租赁,押金返还,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_5f5496bc','（2025）鄂01民初14778号','晴川家园维修责任合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-04-21','承租人林某、出租人罗某','晴川家园维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约5291元。','晴川家园的租赁关系建立后出现“卫生间渗水后双方对维修期限产生分歧”问题，中介未能提供完整的服务过程记录，承租人与出租人随后就书面附件和实际损失各自举证。','审理晴川家园维修责任争议时，合议庭先核对报修工单和现场检测报告，再比对合同附件和通知记录，根据现有证据，出租人知悉后未及时维修应承担相应责任，责任应按实际影响划分。','裁判要点是出租人知悉后未及时维修应承担相应责任，在晴川家园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','晴川家园维修责任事项最终按“承担维修费并赔偿合理损失”执行，经核算，支持金额为713元，超出证据范围的部分不予支持。','调解','武汉,租赁,维修责任,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_614e7c2c','（2024）鄂0102民初14879号','晴川里巷门宽说明合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2024-06-16','承租人周某、出租人许某','晴川里巷门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约19926元。','围绕晴川里巷房屋，双方确认发生过中介口头承诺入口门宽但交付时测量不符，由于房屋交接表未记载争议项目，押金、维修或服务费用的承担方式未能协商一致。','晴川里巷案卷中的聊天记录和门宽测量照片与时间记录可以相互印证，法院据此认为关键居住条件构成订约基础时应如实说明，并对双方未写入合同的承诺从严审查。','法院在晴川里巷案件中明确关键居住条件构成订约基础时应如实说明，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对晴川里巷作出处理：退还服务费并调整违约责任，已查明损失按7247元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,门宽说明,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_15107283','（2024）鄂0111民初23719号','晴川社区电梯停运合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-09-18','承租人顾某、出租人韩某','晴川社区电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约7678元。','本案源于晴川社区交付后的电梯停运事项，承租人提交材料称高层住宅电梯长期停运影响正常使用，出租人则以“双方曾通过物业协调但未达成一致”解释其处理过程。','对于晴川社区发生的电梯停运问题，法院以物业公告和维保记录为核心判断材料，综合交付状态和后续补救情况，持续停运达到影响居住程度时可酌情减租。','晴川社区案确认：持续停运达到影响居住程度时可酌情减租，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就晴川社区争议，法院判令按影响期间减免部分租金，凭证支持的金额核定为5282元，其余请求分别处理。','驳回','武汉,租赁,电梯停运,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_69cfed55','（2023）鄂0106民初16936号','晴川新苑通道占用合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-06-01','承租人陈某、出租人吴某','晴川新苑通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约23604元。','承租人陈入住晴川新苑后主张公共坡道被电动车和杂物反复占用，晴川新苑交接过程中，出租人提交了维修报价和付款凭证，双方遂对通知时间和费用范围产生分歧。','法院针对晴川新苑审查了现场视频和物业投诉记录，这些材料能够证明交易经过，结合双方履行顺序，可认定管理方接报后应采取合理清理措施，未被其他证据支持的口头说法不作为主要依据。','裁判要点是管理方接报后应采取合理清理措施，在晴川新苑租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','晴川新苑通道占用事项最终按“限期清理并完善巡查”执行，经核算，支持金额为14546元，超出证据范围的部分不予支持。','驳回','武汉,租赁,通道占用,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ae11e30d','（2023）鄂01民初25639号','晴川华庭中介服务费合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2023-01-25','承租人唐某、出租人蒋某','晴川华庭中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约5467元。','晴川华庭的租赁关系建立后出现“签约未成后中介收取全部服务费”问题，房屋交接表未记载争议项目，承租人与出租人随后就书面附件和实际损失各自举证。','审理晴川华庭中介服务费争议时，合议庭先核对服务协议和带看记录，再比对合同附件和通知记录，根据现有证据，服务未完整履行时应结合实际工作量确定费用，责任应按实际影响划分。','法院在晴川华庭案件中明确服务未完整履行时应结合实际工作量确定费用，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对晴川华庭作出处理：退还未实际发生的服务费，已查明损失按2074元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,中介服务费,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_41de178c','（2023）鄂0102民初26073号','晴川街区提前退租合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-03-07','承租人罗某、出租人叶某','晴川街区提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约20787元。','围绕晴川街区房屋，双方确认发生过承租人因居住条件变化要求提前解除，由于房屋交接表未记载争议项目，押金、维修或服务费用的承担方式未能协商一致。','晴川街区案卷中的合同附件和沟通邮件与时间记录可以相互印证，法院据此认为违约金过高且损失有限时可依法调整，并对双方未写入合同的承诺从严审查。','晴川街区案确认：违约金过高且损失有限时可依法调整，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就晴川街区争议，法院判令按实际损失承担适当责任，凭证支持的金额核定为5468元，其余请求分别处理。','部分支持','武汉,租赁,提前退租,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_dc521dd9','（2024）鄂0111民初5174号','晴川邻里身份材料合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-10-07','承租人许某、出租人沈某','晴川邻里身份材料纠纷：中介在签约前索取过多证件照片，争议金额约16679元。','本案源于晴川邻里交付后的身份材料事项，承租人提交材料称中介在签约前索取过多证件照片，出租人则以“房屋交接表未记载争议项目”解释其处理过程。','对于晴川邻里发生的身份材料问题，法院以信息收集页面和聊天记录为核心判断材料，综合交付状态和后续补救情况，租赁核验应遵循目的明确和最小必要原则。','裁判要点是租赁核验应遵循目的明确和最小必要原则，在晴川邻里租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','晴川邻里身份材料事项最终按“删除无关材料并停止继续处理”执行，经核算，支持金额为6797元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,身份材料,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e25acc12','（2023）鄂0106民初18889号','晴川小院书面附件合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-10-27','承租人韩某、出租人林某','晴川小院书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约23675元。','承租人韩入住晴川小院后主张双方对坡道维修和清洁费口头承诺发生争议，晴川小院交接过程中，出租人提交了维修报价和付款凭证，双方遂对通知时间和费用范围产生分歧。','法院针对晴川小院审查了合同草案和录音摘要，这些材料能够证明交易经过，结合双方履行顺序，可认定能够写入附件的关键事项应以书面约定为主要依据，未被其他证据支持的口头说法不作为主要依据。','法院在晴川小院案件中明确能够写入附件的关键事项应以书面约定为主要依据，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对晴川小院作出处理：依有效书面条款确定责任，已查明损失按15484元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,书面附件,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_18be3e75','（2024）鄂01民初23519号','晴川住区噪音减租合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-12-11','承租人吴某、出租人周某','晴川住区噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约25520元。','晴川住区的租赁关系建立后出现“长期施工噪音超过合理生活容忍范围”问题，出租人提交了维修报价和付款凭证，承租人与出租人随后就书面附件和实际损失各自举证。','审理晴川住区噪音减租争议时，合议庭先核对施工通知和连续录音记录，再比对合同附件和通知记录，根据现有证据，出租人明知重大影响仍未披露时应承担责任，责任应按实际影响划分。','晴川住区案确认：出租人明知重大影响仍未披露时应承担责任，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就晴川住区争议，法院判令酌情减免受影响期间租金，凭证支持的金额核定为3191元，其余请求分别处理。','支持','武汉,租赁,噪音减租,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_946f323e','（2024）鄂0102民初12459号','晴川宿舍押金返还合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2024-10-07','承租人蒋某、出租人顾某','晴川宿舍押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约17698元。','围绕晴川宿舍房屋，双方确认发生过出租人以深度保洁为由扣留押金，由于双方曾通过物业协调但未达成一致，押金、维修或服务费用的承担方式未能协商一致。','晴川宿舍案卷中的转账记录和交接照片与时间记录可以相互印证，法院据此认为正常使用痕迹不能当然认定为损坏，并对双方未写入合同的承诺从严审查。','裁判要点是正常使用痕迹不能当然认定为损坏，在晴川宿舍租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','晴川宿舍押金返还事项最终按“返还未证明损失部分的押金”执行，经核算，支持金额为5891元，超出证据范围的部分不予支持。','支持','武汉,租赁,押金返还,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_f7847693','（2024）鄂0111民初3214号','晴川雅庭维修责任合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-11-11','承租人叶某、出租人陈某','晴川雅庭维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约17193元。','本案源于晴川雅庭交付后的维修责任事项，承租人提交材料称卫生间渗水后双方对维修期限产生分歧，出租人则以“承租人在发现问题后及时发送书面通知”解释其处理过程。','对于晴川雅庭发生的维修责任问题，法院以报修工单和现场检测报告为核心判断材料，综合交付状态和后续补救情况，出租人知悉后未及时维修应承担相应责任。','法院在晴川雅庭案件中明确出租人知悉后未及时维修应承担相应责任，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对晴川雅庭作出处理：承担维修费并赔偿合理损失，已查明损失按14501元计入责任，其余由双方依合同继续履行。','调解','武汉,租赁,维修责任,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_47e2b60d','（2023）鄂0106民初16128号','晴川春晓门宽说明合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-01-10','承租人沈某、出租人唐某','晴川春晓门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约28858元。','承租人沈入住晴川春晓后主张中介口头承诺入口门宽但交付时测量不符，晴川春晓交接过程中，双方曾通过物业协调但未达成一致，双方遂对通知时间和费用范围产生分歧。','法院针对晴川春晓审查了聊天记录和门宽测量照片，这些材料能够证明交易经过，结合双方履行顺序，可认定关键居住条件构成订约基础时应如实说明，未被其他证据支持的口头说法不作为主要依据。','晴川春晓案确认：关键居住条件构成订约基础时应如实说明，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就晴川春晓争议，法院判令退还服务费并调整违约责任，凭证支持的金额核定为26639元，其余请求分别处理。','支持','武汉,租赁,门宽说明,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ae8bb8fb','（2023）鄂01民初23094号','晴川和园电梯停运合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2023-02-02','承租人林某、出租人罗某','晴川和园电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约35981元。','晴川和园的租赁关系建立后出现“高层住宅电梯长期停运影响正常使用”问题，双方曾通过物业协调但未达成一致，承租人与出租人随后就书面附件和实际损失各自举证。','审理晴川和园电梯停运争议时，合议庭先核对物业公告和维保记录，再比对合同附件和通知记录，根据现有证据，持续停运达到影响居住程度时可酌情减租，责任应按实际影响划分。','裁判要点是持续停运达到影响居住程度时可酌情减租，在晴川和园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','晴川和园电梯停运事项最终按“按影响期间减免部分租金”执行，经核算，支持金额为11174元，超出证据范围的部分不予支持。','支持','武汉,租赁,电梯停运,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_81776405','（2024）鄂0102民初27497号','晴川清庭通道占用合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2024-03-19','承租人周某、出租人许某','晴川清庭通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约14421元。','围绕晴川清庭房屋，双方确认发生过公共坡道被电动车和杂物反复占用，由于出租人提交了维修报价和付款凭证，押金、维修或服务费用的承担方式未能协商一致。','晴川清庭案卷中的现场视频和物业投诉记录与时间记录可以相互印证，法院据此认为管理方接报后应采取合理清理措施，并对双方未写入合同的承诺从严审查。','法院在晴川清庭案件中明确管理方接报后应采取合理清理措施，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对晴川清庭作出处理：限期清理并完善巡查，已查明损失按7892元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,通道占用,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_6f0590f5','（2024）鄂0111民初15805号','汉水公寓中介服务费合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-03-12','承租人顾某、出租人韩某','汉水公寓中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约33885元。','本案源于汉水公寓交付后的中介服务费事项，承租人提交材料称签约未成后中介收取全部服务费，出租人则以“出租人提交了维修报价和付款凭证”解释其处理过程。','对于汉水公寓发生的中介服务费问题，法院以服务协议和带看记录为核心判断材料，综合交付状态和后续补救情况，服务未完整履行时应结合实际工作量确定费用。','汉水公寓案确认：服务未完整履行时应结合实际工作量确定费用，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就汉水公寓争议，法院判令退还未实际发生的服务费，凭证支持的金额核定为31204元，其余请求分别处理。','支持','武汉,租赁,中介服务费,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_b898feb0','（2023）鄂0106民初26734号','汉水家园提前退租合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-12-09','承租人陈某、出租人吴某','汉水家园提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约34771元。','承租人陈入住汉水家园后主张承租人因居住条件变化要求提前解除，汉水家园交接过程中，承租人在发现问题后及时发送书面通知，双方遂对通知时间和费用范围产生分歧。','法院针对汉水家园审查了合同附件和沟通邮件，这些材料能够证明交易经过，结合双方履行顺序，可认定违约金过高且损失有限时可依法调整，未被其他证据支持的口头说法不作为主要依据。','裁判要点是违约金过高且损失有限时可依法调整，在汉水家园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','汉水家园提前退租事项最终按“按实际损失承担适当责任”执行，经核算，支持金额为24563元，超出证据范围的部分不予支持。','调解','武汉,租赁,提前退租,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e0c5bbff','（2025）鄂01民初6515号','汉水里巷身份材料合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-03-20','承租人唐某、出租人蒋某','汉水里巷身份材料纠纷：中介在签约前索取过多证件照片，争议金额约13030元。','汉水里巷的租赁关系建立后出现“中介在签约前索取过多证件照片”问题，房屋交接表未记载争议项目，承租人与出租人随后就书面附件和实际损失各自举证。','审理汉水里巷身份材料争议时，合议庭先核对信息收集页面和聊天记录，再比对合同附件和通知记录，根据现有证据，租赁核验应遵循目的明确和最小必要原则，责任应按实际影响划分。','法院在汉水里巷案件中明确租赁核验应遵循目的明确和最小必要原则，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对汉水里巷作出处理：删除无关材料并停止继续处理，已查明损失按3746元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,身份材料,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_97bfede7','（2023）鄂0102民初15911号','汉水社区书面附件合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-03-20','承租人罗某、出租人叶某','汉水社区书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约35944元。','围绕汉水社区房屋，双方确认发生过双方对坡道维修和清洁费口头承诺发生争议，由于双方曾通过物业协调但未达成一致，押金、维修或服务费用的承担方式未能协商一致。','汉水社区案卷中的合同草案和录音摘要与时间记录可以相互印证，法院据此认为能够写入附件的关键事项应以书面约定为主要依据，并对双方未写入合同的承诺从严审查。','汉水社区案确认：能够写入附件的关键事项应以书面约定为主要依据，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就汉水社区争议，法院判令依有效书面条款确定责任，凭证支持的金额核定为26322元，其余请求分别处理。','调解','武汉,租赁,书面附件,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_84290841','（2025）鄂0111民初4642号','汉水新苑噪音减租合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-10-07','承租人许某、出租人沈某','汉水新苑噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约21376元。','本案源于汉水新苑交付后的噪音减租事项，承租人提交材料称长期施工噪音超过合理生活容忍范围，出租人则以“承租人在发现问题后及时发送书面通知”解释其处理过程。','对于汉水新苑发生的噪音减租问题，法院以施工通知和连续录音记录为核心判断材料，综合交付状态和后续补救情况，出租人明知重大影响仍未披露时应承担责任。','裁判要点是出租人明知重大影响仍未披露时应承担责任，在汉水新苑租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','汉水新苑噪音减租事项最终按“酌情减免受影响期间租金”执行，经核算，支持金额为15313元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,噪音减租,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_c67f320c','（2023）鄂0106民初11380号','汉水华庭押金返还合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-12-28','承租人韩某、出租人林某','汉水华庭押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约29947元。','承租人韩入住汉水华庭后主张出租人以深度保洁为由扣留押金，汉水华庭交接过程中，中介未能提供完整的服务过程记录，双方遂对通知时间和费用范围产生分歧。','法院针对汉水华庭审查了转账记录和交接照片，这些材料能够证明交易经过，结合双方履行顺序，可认定正常使用痕迹不能当然认定为损坏，未被其他证据支持的口头说法不作为主要依据。','法院在汉水华庭案件中明确正常使用痕迹不能当然认定为损坏，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对汉水华庭作出处理：返还未证明损失部分的押金，已查明损失按4571元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,押金返还,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_70f6f80b','（2024）鄂01民初21866号','汉水街区维修责任合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-11-04','承租人吴某、出租人周某','汉水街区维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约12549元。','汉水街区的租赁关系建立后出现“卫生间渗水后双方对维修期限产生分歧”问题，中介未能提供完整的服务过程记录，承租人与出租人随后就书面附件和实际损失各自举证。','审理汉水街区维修责任争议时，合议庭先核对报修工单和现场检测报告，再比对合同附件和通知记录，根据现有证据，出租人知悉后未及时维修应承担相应责任，责任应按实际影响划分。','汉水街区案确认：出租人知悉后未及时维修应承担相应责任，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就汉水街区争议，法院判令承担维修费并赔偿合理损失，凭证支持的金额核定为8816元，其余请求分别处理。','调解','武汉,租赁,维修责任,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_03e2cce1','（2023）鄂0102民初2656号','汉水邻里门宽说明合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-02-19','承租人蒋某、出租人顾某','汉水邻里门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约13219元。','围绕汉水邻里房屋，双方确认发生过中介口头承诺入口门宽但交付时测量不符，由于出租人提交了维修报价和付款凭证，押金、维修或服务费用的承担方式未能协商一致。','汉水邻里案卷中的聊天记录和门宽测量照片与时间记录可以相互印证，法院据此认为关键居住条件构成订约基础时应如实说明，并对双方未写入合同的承诺从严审查。','裁判要点是关键居住条件构成订约基础时应如实说明，在汉水邻里租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','汉水邻里门宽说明事项最终按“退还服务费并调整违约责任”执行，经核算，支持金额为7197元，超出证据范围的部分不予支持。','驳回','武汉,租赁,门宽说明,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_52b286eb','（2024）鄂0111民初23169号','汉水小院电梯停运合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-10-22','承租人叶某、出租人陈某','汉水小院电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约3196元。','本案源于汉水小院交付后的电梯停运事项，承租人提交材料称高层住宅电梯长期停运影响正常使用，出租人则以“双方曾通过物业协调但未达成一致”解释其处理过程。','对于汉水小院发生的电梯停运问题，法院以物业公告和维保记录为核心判断材料，综合交付状态和后续补救情况，持续停运达到影响居住程度时可酌情减租。','法院在汉水小院案件中明确持续停运达到影响居住程度时可酌情减租，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对汉水小院作出处理：按影响期间减免部分租金，已查明损失按2210元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,电梯停运,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_947255d0','（2025）鄂0106民初25904号','汉水住区通道占用合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-05-06','承租人沈某、出租人唐某','汉水住区通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约24776元。','承租人沈入住汉水住区后主张公共坡道被电动车和杂物反复占用，汉水住区交接过程中，双方曾通过物业协调但未达成一致，双方遂对通知时间和费用范围产生分歧。','法院针对汉水住区审查了现场视频和物业投诉记录，这些材料能够证明交易经过，结合双方履行顺序，可认定管理方接报后应采取合理清理措施，未被其他证据支持的口头说法不作为主要依据。','汉水住区案确认：管理方接报后应采取合理清理措施，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就汉水住区争议，法院判令限期清理并完善巡查，凭证支持的金额核定为23323元，其余请求分别处理。','驳回','武汉,租赁,通道占用,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8e89d9e9','（2025）鄂01民初16370号','汉水宿舍中介服务费合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-11-16','承租人林某、出租人罗某','汉水宿舍中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约22620元。','汉水宿舍的租赁关系建立后出现“签约未成后中介收取全部服务费”问题，双方曾通过物业协调但未达成一致，承租人与出租人随后就书面附件和实际损失各自举证。','审理汉水宿舍中介服务费争议时，合议庭先核对服务协议和带看记录，再比对合同附件和通知记录，根据现有证据，服务未完整履行时应结合实际工作量确定费用，责任应按实际影响划分。','裁判要点是服务未完整履行时应结合实际工作量确定费用，在汉水宿舍租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','汉水宿舍中介服务费事项最终按“退还未实际发生的服务费”执行，经核算，支持金额为20560元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,中介服务费,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8d301638','（2024）鄂0102民初21870号','汉水雅庭提前退租合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2024-08-17','承租人周某、出租人许某','汉水雅庭提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约34081元。','围绕汉水雅庭房屋，双方确认发生过承租人因居住条件变化要求提前解除，由于出租人提交了维修报价和付款凭证，押金、维修或服务费用的承担方式未能协商一致。','汉水雅庭案卷中的合同附件和沟通邮件与时间记录可以相互印证，法院据此认为违约金过高且损失有限时可依法调整，并对双方未写入合同的承诺从严审查。','法院在汉水雅庭案件中明确违约金过高且损失有限时可依法调整，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对汉水雅庭作出处理：按实际损失承担适当责任，已查明损失按7756元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,提前退租,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_27fea30d','（2025）鄂0111民初29318号','汉水春晓身份材料合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-03-25','承租人顾某、出租人韩某','汉水春晓身份材料纠纷：中介在签约前索取过多证件照片，争议金额约29591元。','本案源于汉水春晓交付后的身份材料事项，承租人提交材料称中介在签约前索取过多证件照片，出租人则以“房屋交接表未记载争议项目”解释其处理过程。','对于汉水春晓发生的身份材料问题，法院以信息收集页面和聊天记录为核心判断材料，综合交付状态和后续补救情况，租赁核验应遵循目的明确和最小必要原则。','汉水春晓案确认：租赁核验应遵循目的明确和最小必要原则，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就汉水春晓争议，法院判令删除无关材料并停止继续处理，凭证支持的金额核定为1949元，其余请求分别处理。','部分支持','武汉,租赁,身份材料,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_9f391bcc','（2023）鄂0106民初13117号','汉水和园书面附件合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-07-09','承租人陈某、出租人吴某','汉水和园书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约16578元。','承租人陈入住汉水和园后主张双方对坡道维修和清洁费口头承诺发生争议，汉水和园交接过程中，出租人提交了维修报价和付款凭证，双方遂对通知时间和费用范围产生分歧。','法院针对汉水和园审查了合同草案和录音摘要，这些材料能够证明交易经过，结合双方履行顺序，可认定能够写入附件的关键事项应以书面约定为主要依据，未被其他证据支持的口头说法不作为主要依据。','裁判要点是能够写入附件的关键事项应以书面约定为主要依据，在汉水和园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','汉水和园书面附件事项最终按“依有效书面条款确定责任”执行，经核算，支持金额为13785元，超出证据范围的部分不予支持。','驳回','武汉,租赁,书面附件,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e9a7d93d','（2024）鄂01民初15243号','汉水清庭噪音减租合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-06-10','承租人唐某、出租人蒋某','汉水清庭噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约31955元。','汉水清庭的租赁关系建立后出现“长期施工噪音超过合理生活容忍范围”问题，房屋交接表未记载争议项目，承租人与出租人随后就书面附件和实际损失各自举证。','审理汉水清庭噪音减租争议时，合议庭先核对施工通知和连续录音记录，再比对合同附件和通知记录，根据现有证据，出租人明知重大影响仍未披露时应承担责任，责任应按实际影响划分。','法院在汉水清庭案件中明确出租人明知重大影响仍未披露时应承担责任，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对汉水清庭作出处理：酌情减免受影响期间租金，已查明损失按15321元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,噪音减租,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_4fc13b54','（2023）鄂0102民初13261号','沙湖公寓押金返还合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-04-01','承租人罗某、出租人叶某','沙湖公寓押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约32455元。','围绕沙湖公寓房屋，双方确认发生过出租人以深度保洁为由扣留押金，由于中介未能提供完整的服务过程记录，押金、维修或服务费用的承担方式未能协商一致。','沙湖公寓案卷中的转账记录和交接照片与时间记录可以相互印证，法院据此认为正常使用痕迹不能当然认定为损坏，并对双方未写入合同的承诺从严审查。','沙湖公寓案确认：正常使用痕迹不能当然认定为损坏，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就沙湖公寓争议，法院判令返还未证明损失部分的押金，凭证支持的金额核定为10561元，其余请求分别处理。','支持','武汉,租赁,押金返还,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_331b9f60','（2023）鄂0111民初2868号','沙湖家园维修责任合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2023-07-12','承租人许某、出租人沈某','沙湖家园维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约18486元。','本案源于沙湖家园交付后的维修责任事项，承租人提交材料称卫生间渗水后双方对维修期限产生分歧，出租人则以“出租人提交了维修报价和付款凭证”解释其处理过程。','对于沙湖家园发生的维修责任问题，法院以报修工单和现场检测报告为核心判断材料，综合交付状态和后续补救情况，出租人知悉后未及时维修应承担相应责任。','裁判要点是出租人知悉后未及时维修应承担相应责任，在沙湖家园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','沙湖家园维修责任事项最终按“承担维修费并赔偿合理损失”执行，经核算，支持金额为2164元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,维修责任,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_0a176077','（2025）鄂0106民初28352号','沙湖里巷门宽说明合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-01-26','承租人韩某、出租人林某','沙湖里巷门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约21117元。','承租人韩入住沙湖里巷后主张中介口头承诺入口门宽但交付时测量不符，沙湖里巷交接过程中，房屋交接表未记载争议项目，双方遂对通知时间和费用范围产生分歧。','法院针对沙湖里巷审查了聊天记录和门宽测量照片，这些材料能够证明交易经过，结合双方履行顺序，可认定关键居住条件构成订约基础时应如实说明，未被其他证据支持的口头说法不作为主要依据。','法院在沙湖里巷案件中明确关键居住条件构成订约基础时应如实说明，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对沙湖里巷作出处理：退还服务费并调整违约责任，已查明损失按3106元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,门宽说明,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_739ec239','（2025）鄂01民初17245号','沙湖社区电梯停运合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-11-25','承租人吴某、出租人周某','沙湖社区电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约24507元。','沙湖社区的租赁关系建立后出现“高层住宅电梯长期停运影响正常使用”问题，出租人提交了维修报价和付款凭证，承租人与出租人随后就书面附件和实际损失各自举证。','审理沙湖社区电梯停运争议时，合议庭先核对物业公告和维保记录，再比对合同附件和通知记录，根据现有证据，持续停运达到影响居住程度时可酌情减租，责任应按实际影响划分。','沙湖社区案确认：持续停运达到影响居住程度时可酌情减租，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就沙湖社区争议，法院判令按影响期间减免部分租金，凭证支持的金额核定为12817元，其余请求分别处理。','部分支持','武汉,租赁,电梯停运,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_2acff2ef','（2024）鄂0102民初10022号','沙湖新苑通道占用合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2024-01-25','承租人蒋某、出租人顾某','沙湖新苑通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约7137元。','围绕沙湖新苑房屋，双方确认发生过公共坡道被电动车和杂物反复占用，由于出租人提交了维修报价和付款凭证，押金、维修或服务费用的承担方式未能协商一致。','沙湖新苑案卷中的现场视频和物业投诉记录与时间记录可以相互印证，法院据此认为管理方接报后应采取合理清理措施，并对双方未写入合同的承诺从严审查。','裁判要点是管理方接报后应采取合理清理措施，在沙湖新苑租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','沙湖新苑通道占用事项最终按“限期清理并完善巡查”执行，经核算，支持金额为3030元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,通道占用,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_de59a339','（2023）鄂0111民初22496号','沙湖华庭中介服务费合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2023-12-24','承租人叶某、出租人陈某','沙湖华庭中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约5896元。','本案源于沙湖华庭交付后的中介服务费事项，承租人提交材料称签约未成后中介收取全部服务费，出租人则以“中介未能提供完整的服务过程记录”解释其处理过程。','对于沙湖华庭发生的中介服务费问题，法院以服务协议和带看记录为核心判断材料，综合交付状态和后续补救情况，服务未完整履行时应结合实际工作量确定费用。','法院在沙湖华庭案件中明确服务未完整履行时应结合实际工作量确定费用，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对沙湖华庭作出处理：退还未实际发生的服务费，已查明损失按745元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,中介服务费,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ab455737','（2023）鄂0106民初28498号','沙湖街区提前退租合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-09-24','承租人沈某、出租人唐某','沙湖街区提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约34133元。','承租人沈入住沙湖街区后主张承租人因居住条件变化要求提前解除，沙湖街区交接过程中，双方曾通过物业协调但未达成一致，双方遂对通知时间和费用范围产生分歧。','法院针对沙湖街区审查了合同附件和沟通邮件，这些材料能够证明交易经过，结合双方履行顺序，可认定违约金过高且损失有限时可依法调整，未被其他证据支持的口头说法不作为主要依据。','沙湖街区案确认：违约金过高且损失有限时可依法调整，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就沙湖街区争议，法院判令按实际损失承担适当责任，凭证支持的金额核定为7682元，其余请求分别处理。','调解','武汉,租赁,提前退租,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1e3a6ff5','（2025）鄂01民初23697号','沙湖邻里身份材料合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-10-27','承租人林某、出租人罗某','沙湖邻里身份材料纠纷：中介在签约前索取过多证件照片，争议金额约21312元。','沙湖邻里的租赁关系建立后出现“中介在签约前索取过多证件照片”问题，中介未能提供完整的服务过程记录，承租人与出租人随后就书面附件和实际损失各自举证。','审理沙湖邻里身份材料争议时，合议庭先核对信息收集页面和聊天记录，再比对合同附件和通知记录，根据现有证据，租赁核验应遵循目的明确和最小必要原则，责任应按实际影响划分。','裁判要点是租赁核验应遵循目的明确和最小必要原则，在沙湖邻里租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','沙湖邻里身份材料事项最终按“删除无关材料并停止继续处理”执行，经核算，支持金额为15858元，超出证据范围的部分不予支持。','调解','武汉,租赁,身份材料,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_2c919b24','（2023）鄂0102民初15231号','沙湖小院书面附件合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-11-10','承租人周某、出租人许某','沙湖小院书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约24484元。','围绕沙湖小院房屋，双方确认发生过双方对坡道维修和清洁费口头承诺发生争议，由于承租人在发现问题后及时发送书面通知，押金、维修或服务费用的承担方式未能协商一致。','沙湖小院案卷中的合同草案和录音摘要与时间记录可以相互印证，法院据此认为能够写入附件的关键事项应以书面约定为主要依据，并对双方未写入合同的承诺从严审查。','法院在沙湖小院案件中明确能够写入附件的关键事项应以书面约定为主要依据，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对沙湖小院作出处理：依有效书面条款确定责任，已查明损失按11374元计入责任，其余由双方依合同继续履行。','调解','武汉,租赁,书面附件,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_343795e4','（2025）鄂0111民初14956号','沙湖住区噪音减租合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-03-05','承租人顾某、出租人韩某','沙湖住区噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约35168元。','本案源于沙湖住区交付后的噪音减租事项，承租人提交材料称长期施工噪音超过合理生活容忍范围，出租人则以“双方曾通过物业协调但未达成一致”解释其处理过程。','对于沙湖住区发生的噪音减租问题，法院以施工通知和连续录音记录为核心判断材料，综合交付状态和后续补救情况，出租人明知重大影响仍未披露时应承担责任。','沙湖住区案确认：出租人明知重大影响仍未披露时应承担责任，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就沙湖住区争议，法院判令酌情减免受影响期间租金，凭证支持的金额核定为4679元，其余请求分别处理。','驳回','武汉,租赁,噪音减租,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_c014d54c','（2024）鄂0106民初4899号','沙湖宿舍押金返还合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-11-22','承租人陈某、出租人吴某','沙湖宿舍押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约16128元。','承租人陈入住沙湖宿舍后主张出租人以深度保洁为由扣留押金，沙湖宿舍交接过程中，承租人在发现问题后及时发送书面通知，双方遂对通知时间和费用范围产生分歧。','法院针对沙湖宿舍审查了转账记录和交接照片，这些材料能够证明交易经过，结合双方履行顺序，可认定正常使用痕迹不能当然认定为损坏，未被其他证据支持的口头说法不作为主要依据。','裁判要点是正常使用痕迹不能当然认定为损坏，在沙湖宿舍租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','沙湖宿舍押金返还事项最终按“返还未证明损失部分的押金”执行，经核算，支持金额为14528元，超出证据范围的部分不予支持。','驳回','武汉,租赁,押金返还,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_c95b0cf3','（2023）鄂01民初16102号','沙湖雅庭维修责任合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2023-05-01','承租人唐某、出租人蒋某','沙湖雅庭维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约30363元。','沙湖雅庭的租赁关系建立后出现“卫生间渗水后双方对维修期限产生分歧”问题，房屋交接表未记载争议项目，承租人与出租人随后就书面附件和实际损失各自举证。','审理沙湖雅庭维修责任争议时，合议庭先核对报修工单和现场检测报告，再比对合同附件和通知记录，根据现有证据，出租人知悉后未及时维修应承担相应责任，责任应按实际影响划分。','法院在沙湖雅庭案件中明确出租人知悉后未及时维修应承担相应责任，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对沙湖雅庭作出处理：承担维修费并赔偿合理损失，已查明损失按8862元计入责任，其余由双方依合同继续履行。','调解','武汉,租赁,维修责任,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_3f86662d','（2023）鄂0102民初27002号','沙湖春晓门宽说明合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-02-27','承租人罗某、出租人叶某','沙湖春晓门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约9532元。','围绕沙湖春晓房屋，双方确认发生过中介口头承诺入口门宽但交付时测量不符，由于中介未能提供完整的服务过程记录，押金、维修或服务费用的承担方式未能协商一致。','沙湖春晓案卷中的聊天记录和门宽测量照片与时间记录可以相互印证，法院据此认为关键居住条件构成订约基础时应如实说明，并对双方未写入合同的承诺从严审查。','沙湖春晓案确认：关键居住条件构成订约基础时应如实说明，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就沙湖春晓争议，法院判令退还服务费并调整违约责任，凭证支持的金额核定为4841元，其余请求分别处理。','调解','武汉,租赁,门宽说明,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_83b57256','（2025）鄂0111民初5162号','沙湖和园电梯停运合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-07-14','承租人许某、出租人沈某','沙湖和园电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约23428元。','本案源于沙湖和园交付后的电梯停运事项，承租人提交材料称高层住宅电梯长期停运影响正常使用，出租人则以“承租人在发现问题后及时发送书面通知”解释其处理过程。','对于沙湖和园发生的电梯停运问题，法院以物业公告和维保记录为核心判断材料，综合交付状态和后续补救情况，持续停运达到影响居住程度时可酌情减租。','裁判要点是持续停运达到影响居住程度时可酌情减租，在沙湖和园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','沙湖和园电梯停运事项最终按“按影响期间减免部分租金”执行，经核算，支持金额为2484元，超出证据范围的部分不予支持。','调解','武汉,租赁,电梯停运,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_85857b4d','（2024）鄂0106民初24480号','沙湖清庭通道占用合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-03-05','承租人韩某、出租人林某','沙湖清庭通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约21914元。','承租人韩入住沙湖清庭后主张公共坡道被电动车和杂物反复占用，沙湖清庭交接过程中，承租人在发现问题后及时发送书面通知，双方遂对通知时间和费用范围产生分歧。','法院针对沙湖清庭审查了现场视频和物业投诉记录，这些材料能够证明交易经过，结合双方履行顺序，可认定管理方接报后应采取合理清理措施，未被其他证据支持的口头说法不作为主要依据。','法院在沙湖清庭案件中明确管理方接报后应采取合理清理措施，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对沙湖清庭作出处理：限期清理并完善巡查，已查明损失按8768元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,通道占用,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e8deb11a','（2025）鄂01民初4003号','关山公寓中介服务费合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-08-11','承租人吴某、出租人周某','关山公寓中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约34989元。','关山公寓的租赁关系建立后出现“签约未成后中介收取全部服务费”问题，承租人在发现问题后及时发送书面通知，承租人与出租人随后就书面附件和实际损失各自举证。','审理关山公寓中介服务费争议时，合议庭先核对服务协议和带看记录，再比对合同附件和通知记录，根据现有证据，服务未完整履行时应结合实际工作量确定费用，责任应按实际影响划分。','关山公寓案确认：服务未完整履行时应结合实际工作量确定费用，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就关山公寓争议，法院判令退还未实际发生的服务费，凭证支持的金额核定为33531元，其余请求分别处理。','支持','武汉,租赁,中介服务费,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_45e327ad','（2023）鄂0102民初2776号','关山家园提前退租合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-11-08','承租人蒋某、出租人顾某','关山家园提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约5331元。','围绕关山家园房屋，双方确认发生过承租人因居住条件变化要求提前解除，由于房屋交接表未记载争议项目，押金、维修或服务费用的承担方式未能协商一致。','关山家园案卷中的合同附件和沟通邮件与时间记录可以相互印证，法院据此认为违约金过高且损失有限时可依法调整，并对双方未写入合同的承诺从严审查。','裁判要点是违约金过高且损失有限时可依法调整，在关山家园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','关山家园提前退租事项最终按“按实际损失承担适当责任”执行，经核算，支持金额为4072元，超出证据范围的部分不予支持。','驳回','武汉,租赁,提前退租,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_09074a15','（2024）鄂0111民初1323号','关山里巷身份材料合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-11-09','承租人叶某、出租人陈某','关山里巷身份材料纠纷：中介在签约前索取过多证件照片，争议金额约958元。','本案源于关山里巷交付后的身份材料事项，承租人提交材料称中介在签约前索取过多证件照片，出租人则以“承租人在发现问题后及时发送书面通知”解释其处理过程。','对于关山里巷发生的身份材料问题，法院以信息收集页面和聊天记录为核心判断材料，综合交付状态和后续补救情况，租赁核验应遵循目的明确和最小必要原则。','法院在关山里巷案件中明确租赁核验应遵循目的明确和最小必要原则，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对关山里巷作出处理：删除无关材料并停止继续处理，已查明损失按472元计入责任，其余由双方依合同继续履行。','调解','武汉,租赁,身份材料,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_b75ec80a','（2025）鄂0106民初2000号','关山社区书面附件合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-07-14','承租人沈某、出租人唐某','关山社区书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约22888元。','承租人沈入住关山社区后主张双方对坡道维修和清洁费口头承诺发生争议，关山社区交接过程中，承租人在发现问题后及时发送书面通知，双方遂对通知时间和费用范围产生分歧。','法院针对关山社区审查了合同草案和录音摘要，这些材料能够证明交易经过，结合双方履行顺序，可认定能够写入附件的关键事项应以书面约定为主要依据，未被其他证据支持的口头说法不作为主要依据。','关山社区案确认：能够写入附件的关键事项应以书面约定为主要依据，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就关山社区争议，法院判令依有效书面条款确定责任，凭证支持的金额核定为20559元，其余请求分别处理。','部分支持','武汉,租赁,书面附件,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e4ba1097','（2024）鄂01民初23628号','关山新苑噪音减租合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-02-22','承租人林某、出租人罗某','关山新苑噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约31587元。','关山新苑的租赁关系建立后出现“长期施工噪音超过合理生活容忍范围”问题，承租人在发现问题后及时发送书面通知，承租人与出租人随后就书面附件和实际损失各自举证。','审理关山新苑噪音减租争议时，合议庭先核对施工通知和连续录音记录，再比对合同附件和通知记录，根据现有证据，出租人明知重大影响仍未披露时应承担责任，责任应按实际影响划分。','裁判要点是出租人明知重大影响仍未披露时应承担责任，在关山新苑租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','关山新苑噪音减租事项最终按“酌情减免受影响期间租金”执行，经核算，支持金额为21776元，超出证据范围的部分不予支持。','驳回','武汉,租赁,噪音减租,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_01b78932','（2025）鄂0102民初17814号','关山华庭押金返还合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2025-04-05','承租人周某、出租人许某','关山华庭押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约33404元。','围绕关山华庭房屋，双方确认发生过出租人以深度保洁为由扣留押金，由于出租人提交了维修报价和付款凭证，押金、维修或服务费用的承担方式未能协商一致。','关山华庭案卷中的转账记录和交接照片与时间记录可以相互印证，法院据此认为正常使用痕迹不能当然认定为损坏，并对双方未写入合同的承诺从严审查。','法院在关山华庭案件中明确正常使用痕迹不能当然认定为损坏，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对关山华庭作出处理：返还未证明损失部分的押金，已查明损失按20337元计入责任，其余由双方依合同继续履行。','调解','武汉,租赁,押金返还,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_da93aeb9','（2024）鄂0111民初3404号','关山街区维修责任合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-01-26','承租人顾某、出租人韩某','关山街区维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约18462元。','本案源于关山街区交付后的维修责任事项，承租人提交材料称卫生间渗水后双方对维修期限产生分歧，出租人则以“出租人提交了维修报价和付款凭证”解释其处理过程。','对于关山街区发生的维修责任问题，法院以报修工单和现场检测报告为核心判断材料，综合交付状态和后续补救情况，出租人知悉后未及时维修应承担相应责任。','关山街区案确认：出租人知悉后未及时维修应承担相应责任，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就关山街区争议，法院判令承担维修费并赔偿合理损失，凭证支持的金额核定为6817元，其余请求分别处理。','部分支持','武汉,租赁,维修责任,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_c757df8d','（2024）鄂0106民初8563号','关山邻里门宽说明合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-04-06','承租人陈某、出租人吴某','关山邻里门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约7211元。','承租人陈入住关山邻里后主张中介口头承诺入口门宽但交付时测量不符，关山邻里交接过程中，承租人在发现问题后及时发送书面通知，双方遂对通知时间和费用范围产生分歧。','法院针对关山邻里审查了聊天记录和门宽测量照片，这些材料能够证明交易经过，结合双方履行顺序，可认定关键居住条件构成订约基础时应如实说明，未被其他证据支持的口头说法不作为主要依据。','裁判要点是关键居住条件构成订约基础时应如实说明，在关山邻里租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','关山邻里门宽说明事项最终按“退还服务费并调整违约责任”执行，经核算，支持金额为410元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,门宽说明,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_514c2353','（2025）鄂01民初19871号','关山小院电梯停运合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-01-03','承租人唐某、出租人蒋某','关山小院电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约12740元。','关山小院的租赁关系建立后出现“高层住宅电梯长期停运影响正常使用”问题，出租人提交了维修报价和付款凭证，承租人与出租人随后就书面附件和实际损失各自举证。','审理关山小院电梯停运争议时，合议庭先核对物业公告和维保记录，再比对合同附件和通知记录，根据现有证据，持续停运达到影响居住程度时可酌情减租，责任应按实际影响划分。','法院在关山小院案件中明确持续停运达到影响居住程度时可酌情减租，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对关山小院作出处理：按影响期间减免部分租金，已查明损失按4712元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,电梯停运,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ca69eca2','（2024）鄂0102民初7287号','关山住区通道占用合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2024-10-02','承租人罗某、出租人叶某','关山住区通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约26385元。','围绕关山住区房屋，双方确认发生过公共坡道被电动车和杂物反复占用，由于双方曾通过物业协调但未达成一致，押金、维修或服务费用的承担方式未能协商一致。','关山住区案卷中的现场视频和物业投诉记录与时间记录可以相互印证，法院据此认为管理方接报后应采取合理清理措施，并对双方未写入合同的承诺从严审查。','关山住区案确认：管理方接报后应采取合理清理措施，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就关山住区争议，法院判令限期清理并完善巡查，凭证支持的金额核定为21404元，其余请求分别处理。','调解','武汉,租赁,通道占用,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_67384789','（2023）鄂0111民初13302号','关山宿舍中介服务费合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2023-09-15','承租人许某、出租人沈某','关山宿舍中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约2178元。','本案源于关山宿舍交付后的中介服务费事项，承租人提交材料称签约未成后中介收取全部服务费，出租人则以“出租人提交了维修报价和付款凭证”解释其处理过程。','对于关山宿舍发生的中介服务费问题，法院以服务协议和带看记录为核心判断材料，综合交付状态和后续补救情况，服务未完整履行时应结合实际工作量确定费用。','裁判要点是服务未完整履行时应结合实际工作量确定费用，在关山宿舍租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','关山宿舍中介服务费事项最终按“退还未实际发生的服务费”执行，经核算，支持金额为2050元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,中介服务费,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_5d63ca21','（2025）鄂0106民初22301号','关山雅庭提前退租合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-11-05','承租人韩某、出租人林某','关山雅庭提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约32514元。','承租人韩入住关山雅庭后主张承租人因居住条件变化要求提前解除，关山雅庭交接过程中，中介未能提供完整的服务过程记录，双方遂对通知时间和费用范围产生分歧。','法院针对关山雅庭审查了合同附件和沟通邮件，这些材料能够证明交易经过，结合双方履行顺序，可认定违约金过高且损失有限时可依法调整，未被其他证据支持的口头说法不作为主要依据。','法院在关山雅庭案件中明确违约金过高且损失有限时可依法调整，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对关山雅庭作出处理：按实际损失承担适当责任，已查明损失按18690元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,提前退租,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_14b5bd0b','（2023）鄂01民初4370号','关山春晓身份材料合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2023-09-01','承租人吴某、出租人周某','关山春晓身份材料纠纷：中介在签约前索取过多证件照片，争议金额约22776元。','关山春晓的租赁关系建立后出现“中介在签约前索取过多证件照片”问题，中介未能提供完整的服务过程记录，承租人与出租人随后就书面附件和实际损失各自举证。','审理关山春晓身份材料争议时，合议庭先核对信息收集页面和聊天记录，再比对合同附件和通知记录，根据现有证据，租赁核验应遵循目的明确和最小必要原则，责任应按实际影响划分。','关山春晓案确认：租赁核验应遵循目的明确和最小必要原则，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就关山春晓争议，法院判令删除无关材料并停止继续处理，凭证支持的金额核定为13041元，其余请求分别处理。','驳回','武汉,租赁,身份材料,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_7e0a8262','（2023）鄂0102民初29260号','关山和园书面附件合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-07-10','承租人蒋某、出租人顾某','关山和园书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约32454元。','围绕关山和园房屋，双方确认发生过双方对坡道维修和清洁费口头承诺发生争议，由于出租人提交了维修报价和付款凭证，押金、维修或服务费用的承担方式未能协商一致。','关山和园案卷中的合同草案和录音摘要与时间记录可以相互印证，法院据此认为能够写入附件的关键事项应以书面约定为主要依据，并对双方未写入合同的承诺从严审查。','裁判要点是能够写入附件的关键事项应以书面约定为主要依据，在关山和园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','关山和园书面附件事项最终按“依有效书面条款确定责任”执行，经核算，支持金额为25137元，超出证据范围的部分不予支持。','支持','武汉,租赁,书面附件,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_37c1ff4b','（2023）鄂0111民初1003号','关山清庭噪音减租合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2023-02-03','承租人叶某、出租人陈某','关山清庭噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约23950元。','本案源于关山清庭交付后的噪音减租事项，承租人提交材料称长期施工噪音超过合理生活容忍范围，出租人则以“出租人提交了维修报价和付款凭证”解释其处理过程。','对于关山清庭发生的噪音减租问题，法院以施工通知和连续录音记录为核心判断材料，综合交付状态和后续补救情况，出租人明知重大影响仍未披露时应承担责任。','法院在关山清庭案件中明确出租人明知重大影响仍未披露时应承担责任，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对关山清庭作出处理：酌情减免受影响期间租金，已查明损失按22475元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,噪音减租,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1d8b68d0','（2023）鄂0106民初9633号','徐东公寓押金返还合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-07-03','承租人沈某、出租人唐某','徐东公寓押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约26267元。','承租人沈入住徐东公寓后主张出租人以深度保洁为由扣留押金，徐东公寓交接过程中，承租人在发现问题后及时发送书面通知，双方遂对通知时间和费用范围产生分歧。','法院针对徐东公寓审查了转账记录和交接照片，这些材料能够证明交易经过，结合双方履行顺序，可认定正常使用痕迹不能当然认定为损坏，未被其他证据支持的口头说法不作为主要依据。','徐东公寓案确认：正常使用痕迹不能当然认定为损坏，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就徐东公寓争议，法院判令返还未证明损失部分的押金，凭证支持的金额核定为8625元，其余请求分别处理。','支持','武汉,租赁,押金返还,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_39cface4','（2024）鄂01民初14910号','徐东家园维修责任合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-04-24','承租人林某、出租人罗某','徐东家园维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约7501元。','徐东家园的租赁关系建立后出现“卫生间渗水后双方对维修期限产生分歧”问题，中介未能提供完整的服务过程记录，承租人与出租人随后就书面附件和实际损失各自举证。','审理徐东家园维修责任争议时，合议庭先核对报修工单和现场检测报告，再比对合同附件和通知记录，根据现有证据，出租人知悉后未及时维修应承担相应责任，责任应按实际影响划分。','裁判要点是出租人知悉后未及时维修应承担相应责任，在徐东家园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','徐东家园维修责任事项最终按“承担维修费并赔偿合理损失”执行，经核算，支持金额为4741元，超出证据范围的部分不予支持。','驳回','武汉,租赁,维修责任,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1d09028c','（2024）鄂0102民初17104号','徐东里巷门宽说明合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2024-03-22','承租人周某、出租人许某','徐东里巷门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约4519元。','围绕徐东里巷房屋，双方确认发生过中介口头承诺入口门宽但交付时测量不符，由于房屋交接表未记载争议项目，押金、维修或服务费用的承担方式未能协商一致。','徐东里巷案卷中的聊天记录和门宽测量照片与时间记录可以相互印证，法院据此认为关键居住条件构成订约基础时应如实说明，并对双方未写入合同的承诺从严审查。','法院在徐东里巷案件中明确关键居住条件构成订约基础时应如实说明，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对徐东里巷作出处理：退还服务费并调整违约责任，已查明损失按1464元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,门宽说明,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_6f076425','（2024）鄂0111民初10061号','徐东社区电梯停运合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-02-09','承租人顾某、出租人韩某','徐东社区电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约25906元。','本案源于徐东社区交付后的电梯停运事项，承租人提交材料称高层住宅电梯长期停运影响正常使用，出租人则以“中介未能提供完整的服务过程记录”解释其处理过程。','对于徐东社区发生的电梯停运问题，法院以物业公告和维保记录为核心判断材料，综合交付状态和后续补救情况，持续停运达到影响居住程度时可酌情减租。','徐东社区案确认：持续停运达到影响居住程度时可酌情减租，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就徐东社区争议，法院判令按影响期间减免部分租金，凭证支持的金额核定为11764元，其余请求分别处理。','驳回','武汉,租赁,电梯停运,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_fd40cfc4','（2024）鄂0106民初6901号','徐东新苑通道占用合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-11-06','承租人陈某、出租人吴某','徐东新苑通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约28004元。','承租人陈入住徐东新苑后主张公共坡道被电动车和杂物反复占用，徐东新苑交接过程中，中介未能提供完整的服务过程记录，双方遂对通知时间和费用范围产生分歧。','法院针对徐东新苑审查了现场视频和物业投诉记录，这些材料能够证明交易经过，结合双方履行顺序，可认定管理方接报后应采取合理清理措施，未被其他证据支持的口头说法不作为主要依据。','裁判要点是管理方接报后应采取合理清理措施，在徐东新苑租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','徐东新苑通道占用事项最终按“限期清理并完善巡查”执行，经核算，支持金额为26500元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,通道占用,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_fe23ba0a','（2024）鄂01民初7037号','徐东华庭中介服务费合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-05-06','承租人唐某、出租人蒋某','徐东华庭中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约32474元。','徐东华庭的租赁关系建立后出现“签约未成后中介收取全部服务费”问题，房屋交接表未记载争议项目，承租人与出租人随后就书面附件和实际损失各自举证。','审理徐东华庭中介服务费争议时，合议庭先核对服务协议和带看记录，再比对合同附件和通知记录，根据现有证据，服务未完整履行时应结合实际工作量确定费用，责任应按实际影响划分。','法院在徐东华庭案件中明确服务未完整履行时应结合实际工作量确定费用，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对徐东华庭作出处理：退还未实际发生的服务费，已查明损失按22729元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,中介服务费,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_3ec87a23','（2024）鄂0102民初10336号','徐东街区提前退租合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2024-08-04','承租人罗某、出租人叶某','徐东街区提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约9466元。','围绕徐东街区房屋，双方确认发生过承租人因居住条件变化要求提前解除，由于中介未能提供完整的服务过程记录，押金、维修或服务费用的承担方式未能协商一致。','徐东街区案卷中的合同附件和沟通邮件与时间记录可以相互印证，法院据此认为违约金过高且损失有限时可依法调整，并对双方未写入合同的承诺从严审查。','徐东街区案确认：违约金过高且损失有限时可依法调整，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就徐东街区争议，法院判令按实际损失承担适当责任，凭证支持的金额核定为774元，其余请求分别处理。','部分支持','武汉,租赁,提前退租,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_6b30650f','（2025）鄂0111民初17557号','徐东邻里身份材料合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-08-09','承租人许某、出租人沈某','徐东邻里身份材料纠纷：中介在签约前索取过多证件照片，争议金额约13136元。','本案源于徐东邻里交付后的身份材料事项，承租人提交材料称中介在签约前索取过多证件照片，出租人则以“房屋交接表未记载争议项目”解释其处理过程。','对于徐东邻里发生的身份材料问题，法院以信息收集页面和聊天记录为核心判断材料，综合交付状态和后续补救情况，租赁核验应遵循目的明确和最小必要原则。','裁判要点是租赁核验应遵循目的明确和最小必要原则，在徐东邻里租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','徐东邻里身份材料事项最终按“删除无关材料并停止继续处理”执行，经核算，支持金额为3898元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,身份材料,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_0f08819c','（2025）鄂0106民初12312号','徐东小院书面附件合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-08-27','承租人韩某、出租人林某','徐东小院书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约24751元。','承租人韩入住徐东小院后主张双方对坡道维修和清洁费口头承诺发生争议，徐东小院交接过程中，承租人在发现问题后及时发送书面通知，双方遂对通知时间和费用范围产生分歧。','法院针对徐东小院审查了合同草案和录音摘要，这些材料能够证明交易经过，结合双方履行顺序，可认定能够写入附件的关键事项应以书面约定为主要依据，未被其他证据支持的口头说法不作为主要依据。','法院在徐东小院案件中明确能够写入附件的关键事项应以书面约定为主要依据，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对徐东小院作出处理：依有效书面条款确定责任，已查明损失按21522元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,书面附件,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1d000dfd','（2024）鄂01民初10624号','徐东住区噪音减租合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-01-16','承租人吴某、出租人周某','徐东住区噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约18968元。','徐东住区的租赁关系建立后出现“长期施工噪音超过合理生活容忍范围”问题，中介未能提供完整的服务过程记录，承租人与出租人随后就书面附件和实际损失各自举证。','审理徐东住区噪音减租争议时，合议庭先核对施工通知和连续录音记录，再比对合同附件和通知记录，根据现有证据，出租人明知重大影响仍未披露时应承担责任，责任应按实际影响划分。','徐东住区案确认：出租人明知重大影响仍未披露时应承担责任，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就徐东住区争议，法院判令酌情减免受影响期间租金，凭证支持的金额核定为10002元，其余请求分别处理。','驳回','武汉,租赁,噪音减租,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_a1eb304b','（2024）鄂0102民初5019号','徐东宿舍押金返还合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2024-11-24','承租人蒋某、出租人顾某','徐东宿舍押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约25242元。','围绕徐东宿舍房屋，双方确认发生过出租人以深度保洁为由扣留押金，由于房屋交接表未记载争议项目，押金、维修或服务费用的承担方式未能协商一致。','徐东宿舍案卷中的转账记录和交接照片与时间记录可以相互印证，法院据此认为正常使用痕迹不能当然认定为损坏，并对双方未写入合同的承诺从严审查。','裁判要点是正常使用痕迹不能当然认定为损坏，在徐东宿舍租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','徐东宿舍押金返还事项最终按“返还未证明损失部分的押金”执行，经核算，支持金额为23528元，超出证据范围的部分不予支持。','驳回','武汉,租赁,押金返还,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e4b65fb5','（2025）鄂0111民初8271号','徐东雅庭维修责任合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-12-13','承租人叶某、出租人陈某','徐东雅庭维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约33481元。','本案源于徐东雅庭交付后的维修责任事项，承租人提交材料称卫生间渗水后双方对维修期限产生分歧，出租人则以“承租人在发现问题后及时发送书面通知”解释其处理过程。','对于徐东雅庭发生的维修责任问题，法院以报修工单和现场检测报告为核心判断材料，综合交付状态和后续补救情况，出租人知悉后未及时维修应承担相应责任。','法院在徐东雅庭案件中明确出租人知悉后未及时维修应承担相应责任，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对徐东雅庭作出处理：承担维修费并赔偿合理损失，已查明损失按18952元计入责任，其余由双方依合同继续履行。','调解','武汉,租赁,维修责任,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_4ff81c1f','（2025）鄂0106民初16417号','徐东春晓门宽说明合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-11-27','承租人沈某、出租人唐某','徐东春晓门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约1000元。','承租人沈入住徐东春晓后主张中介口头承诺入口门宽但交付时测量不符，徐东春晓交接过程中，出租人提交了维修报价和付款凭证，双方遂对通知时间和费用范围产生分歧。','法院针对徐东春晓审查了聊天记录和门宽测量照片，这些材料能够证明交易经过，结合双方履行顺序，可认定关键居住条件构成订约基础时应如实说明，未被其他证据支持的口头说法不作为主要依据。','徐东春晓案确认：关键居住条件构成订约基础时应如实说明，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就徐东春晓争议，法院判令退还服务费并调整违约责任，凭证支持的金额核定为393元，其余请求分别处理。','调解','武汉,租赁,门宽说明,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ddfc4df9','（2023）鄂01民初5239号','徐东和园电梯停运合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2023-10-05','承租人林某、出租人罗某','徐东和园电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约21680元。','徐东和园的租赁关系建立后出现“高层住宅电梯长期停运影响正常使用”问题，出租人提交了维修报价和付款凭证，承租人与出租人随后就书面附件和实际损失各自举证。','审理徐东和园电梯停运争议时，合议庭先核对物业公告和维保记录，再比对合同附件和通知记录，根据现有证据，持续停运达到影响居住程度时可酌情减租，责任应按实际影响划分。','裁判要点是持续停运达到影响居住程度时可酌情减租，在徐东和园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','徐东和园电梯停运事项最终按“按影响期间减免部分租金”执行，经核算，支持金额为6524元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,电梯停运,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_211340e2','（2025）鄂0102民初16243号','徐东清庭通道占用合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2025-05-27','承租人周某、出租人许某','徐东清庭通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约13261元。','围绕徐东清庭房屋，双方确认发生过公共坡道被电动车和杂物反复占用，由于出租人提交了维修报价和付款凭证，押金、维修或服务费用的承担方式未能协商一致。','徐东清庭案卷中的现场视频和物业投诉记录与时间记录可以相互印证，法院据此认为管理方接报后应采取合理清理措施，并对双方未写入合同的承诺从严审查。','法院在徐东清庭案件中明确管理方接报后应采取合理清理措施，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对徐东清庭作出处理：限期清理并完善巡查，已查明损失按4620元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,通道占用,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_f56fd53e','（2023）鄂0111民初17209号','积玉桥公寓中介服务费合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2023-06-06','承租人顾某、出租人韩某','积玉桥公寓中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约12408元。','本案源于积玉桥公寓交付后的中介服务费事项，承租人提交材料称签约未成后中介收取全部服务费，出租人则以“房屋交接表未记载争议项目”解释其处理过程。','对于积玉桥公寓发生的中介服务费问题，法院以服务协议和带看记录为核心判断材料，综合交付状态和后续补救情况，服务未完整履行时应结合实际工作量确定费用。','积玉桥公寓案确认：服务未完整履行时应结合实际工作量确定费用，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就积玉桥公寓争议，法院判令退还未实际发生的服务费，凭证支持的金额核定为2163元，其余请求分别处理。','部分支持','武汉,租赁,中介服务费,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_eabee34f','（2024）鄂0106民初27032号','积玉桥家园提前退租合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-02-24','承租人陈某、出租人吴某','积玉桥家园提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约6503元。','承租人陈入住积玉桥家园后主张承租人因居住条件变化要求提前解除，积玉桥家园交接过程中，出租人提交了维修报价和付款凭证，双方遂对通知时间和费用范围产生分歧。','法院针对积玉桥家园审查了合同附件和沟通邮件，这些材料能够证明交易经过，结合双方履行顺序，可认定违约金过高且损失有限时可依法调整，未被其他证据支持的口头说法不作为主要依据。','裁判要点是违约金过高且损失有限时可依法调整，在积玉桥家园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','积玉桥家园提前退租事项最终按“按实际损失承担适当责任”执行，经核算，支持金额为4549元，超出证据范围的部分不予支持。','驳回','武汉,租赁,提前退租,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8334e808','（2024）鄂01民初2649号','积玉桥里巷身份材料合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-09-16','承租人唐某、出租人蒋某','积玉桥里巷身份材料纠纷：中介在签约前索取过多证件照片，争议金额约1089元。','积玉桥里巷的租赁关系建立后出现“中介在签约前索取过多证件照片”问题，出租人提交了维修报价和付款凭证，承租人与出租人随后就书面附件和实际损失各自举证。','审理积玉桥里巷身份材料争议时，合议庭先核对信息收集页面和聊天记录，再比对合同附件和通知记录，根据现有证据，租赁核验应遵循目的明确和最小必要原则，责任应按实际影响划分。','法院在积玉桥里巷案件中明确租赁核验应遵循目的明确和最小必要原则，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对积玉桥里巷作出处理：删除无关材料并停止继续处理，已查明损失按656元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,身份材料,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_76137f95','（2023）鄂0102民初23135号','积玉桥社区书面附件合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-11-12','承租人罗某、出租人叶某','积玉桥社区书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约15695元。','围绕积玉桥社区房屋，双方确认发生过双方对坡道维修和清洁费口头承诺发生争议，由于双方曾通过物业协调但未达成一致，押金、维修或服务费用的承担方式未能协商一致。','积玉桥社区案卷中的合同草案和录音摘要与时间记录可以相互印证，法院据此认为能够写入附件的关键事项应以书面约定为主要依据，并对双方未写入合同的承诺从严审查。','积玉桥社区案确认：能够写入附件的关键事项应以书面约定为主要依据，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就积玉桥社区争议，法院判令依有效书面条款确定责任，凭证支持的金额核定为6202元，其余请求分别处理。','调解','武汉,租赁,书面附件,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_cb31495c','（2024）鄂0111民初11657号','积玉桥新苑噪音减租合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-06-27','承租人许某、出租人沈某','积玉桥新苑噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约16911元。','本案源于积玉桥新苑交付后的噪音减租事项，承租人提交材料称长期施工噪音超过合理生活容忍范围，出租人则以“出租人提交了维修报价和付款凭证”解释其处理过程。','对于积玉桥新苑发生的噪音减租问题，法院以施工通知和连续录音记录为核心判断材料，综合交付状态和后续补救情况，出租人明知重大影响仍未披露时应承担责任。','裁判要点是出租人明知重大影响仍未披露时应承担责任，在积玉桥新苑租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','积玉桥新苑噪音减租事项最终按“酌情减免受影响期间租金”执行，经核算，支持金额为5351元，超出证据范围的部分不予支持。','驳回','武汉,租赁,噪音减租,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8f9604df','（2024）鄂0106民初4602号','积玉桥华庭押金返还合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-01-14','承租人韩某、出租人林某','积玉桥华庭押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约31565元。','承租人韩入住积玉桥华庭后主张出租人以深度保洁为由扣留押金，积玉桥华庭交接过程中，承租人在发现问题后及时发送书面通知，双方遂对通知时间和费用范围产生分歧。','法院针对积玉桥华庭审查了转账记录和交接照片，这些材料能够证明交易经过，结合双方履行顺序，可认定正常使用痕迹不能当然认定为损坏，未被其他证据支持的口头说法不作为主要依据。','法院在积玉桥华庭案件中明确正常使用痕迹不能当然认定为损坏，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对积玉桥华庭作出处理：返还未证明损失部分的押金，已查明损失按28134元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,押金返还,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_416e2f0f','（2025）鄂01民初15788号','积玉桥街区维修责任合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-12-11','承租人吴某、出租人周某','积玉桥街区维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约31896元。','积玉桥街区的租赁关系建立后出现“卫生间渗水后双方对维修期限产生分歧”问题，出租人提交了维修报价和付款凭证，承租人与出租人随后就书面附件和实际损失各自举证。','审理积玉桥街区维修责任争议时，合议庭先核对报修工单和现场检测报告，再比对合同附件和通知记录，根据现有证据，出租人知悉后未及时维修应承担相应责任，责任应按实际影响划分。','积玉桥街区案确认：出租人知悉后未及时维修应承担相应责任，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就积玉桥街区争议，法院判令承担维修费并赔偿合理损失，凭证支持的金额核定为2896元，其余请求分别处理。','驳回','武汉,租赁,维修责任,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_32ec0b4e','（2024）鄂0102民初16089号','积玉桥邻里门宽说明合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2024-05-17','承租人蒋某、出租人顾某','积玉桥邻里门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约3558元。','围绕积玉桥邻里房屋，双方确认发生过中介口头承诺入口门宽但交付时测量不符，由于承租人在发现问题后及时发送书面通知，押金、维修或服务费用的承担方式未能协商一致。','积玉桥邻里案卷中的聊天记录和门宽测量照片与时间记录可以相互印证，法院据此认为关键居住条件构成订约基础时应如实说明，并对双方未写入合同的承诺从严审查。','裁判要点是关键居住条件构成订约基础时应如实说明，在积玉桥邻里租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','积玉桥邻里门宽说明事项最终按“退还服务费并调整违约责任”执行，经核算，支持金额为1178元，超出证据范围的部分不予支持。','调解','武汉,租赁,门宽说明,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e310e94a','（2025）鄂0111民初28157号','积玉桥小院电梯停运合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-08-11','承租人叶某、出租人陈某','积玉桥小院电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约5941元。','本案源于积玉桥小院交付后的电梯停运事项，承租人提交材料称高层住宅电梯长期停运影响正常使用，出租人则以“出租人提交了维修报价和付款凭证”解释其处理过程。','对于积玉桥小院发生的电梯停运问题，法院以物业公告和维保记录为核心判断材料，综合交付状态和后续补救情况，持续停运达到影响居住程度时可酌情减租。','法院在积玉桥小院案件中明确持续停运达到影响居住程度时可酌情减租，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对积玉桥小院作出处理：按影响期间减免部分租金，已查明损失按3935元计入责任，其余由双方依合同继续履行。','调解','武汉,租赁,电梯停运,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8c97a94b','（2025）鄂0106民初5793号','积玉桥住区通道占用合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-01-06','承租人沈某、出租人唐某','积玉桥住区通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约7658元。','承租人沈入住积玉桥住区后主张公共坡道被电动车和杂物反复占用，积玉桥住区交接过程中，承租人在发现问题后及时发送书面通知，双方遂对通知时间和费用范围产生分歧。','法院针对积玉桥住区审查了现场视频和物业投诉记录，这些材料能够证明交易经过，结合双方履行顺序，可认定管理方接报后应采取合理清理措施，未被其他证据支持的口头说法不作为主要依据。','积玉桥住区案确认：管理方接报后应采取合理清理措施，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就积玉桥住区争议，法院判令限期清理并完善巡查，凭证支持的金额核定为3376元，其余请求分别处理。','支持','武汉,租赁,通道占用,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_069f5f1a','（2024）鄂01民初19563号','积玉桥宿舍中介服务费合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-09-21','承租人林某、出租人罗某','积玉桥宿舍中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约15529元。','积玉桥宿舍的租赁关系建立后出现“签约未成后中介收取全部服务费”问题，双方曾通过物业协调但未达成一致，承租人与出租人随后就书面附件和实际损失各自举证。','审理积玉桥宿舍中介服务费争议时，合议庭先核对服务协议和带看记录，再比对合同附件和通知记录，根据现有证据，服务未完整履行时应结合实际工作量确定费用，责任应按实际影响划分。','裁判要点是服务未完整履行时应结合实际工作量确定费用，在积玉桥宿舍租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','积玉桥宿舍中介服务费事项最终按“退还未实际发生的服务费”执行，经核算，支持金额为12302元，超出证据范围的部分不予支持。','调解','武汉,租赁,中介服务费,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e477475c','（2025）鄂0102民初27690号','积玉桥雅庭提前退租合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2025-03-04','承租人周某、出租人许某','积玉桥雅庭提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约6720元。','围绕积玉桥雅庭房屋，双方确认发生过承租人因居住条件变化要求提前解除，由于中介未能提供完整的服务过程记录，押金、维修或服务费用的承担方式未能协商一致。','积玉桥雅庭案卷中的合同附件和沟通邮件与时间记录可以相互印证，法院据此认为违约金过高且损失有限时可依法调整，并对双方未写入合同的承诺从严审查。','法院在积玉桥雅庭案件中明确违约金过高且损失有限时可依法调整，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对积玉桥雅庭作出处理：按实际损失承担适当责任，已查明损失按6264元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,提前退租,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_81e192e5','（2023）鄂0111民初16898号','积玉桥春晓身份材料合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2023-10-21','承租人顾某、出租人韩某','积玉桥春晓身份材料纠纷：中介在签约前索取过多证件照片，争议金额约18313元。','本案源于积玉桥春晓交付后的身份材料事项，承租人提交材料称中介在签约前索取过多证件照片，出租人则以“出租人提交了维修报价和付款凭证”解释其处理过程。','对于积玉桥春晓发生的身份材料问题，法院以信息收集页面和聊天记录为核心判断材料，综合交付状态和后续补救情况，租赁核验应遵循目的明确和最小必要原则。','积玉桥春晓案确认：租赁核验应遵循目的明确和最小必要原则，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就积玉桥春晓争议，法院判令删除无关材料并停止继续处理，凭证支持的金额核定为12417元，其余请求分别处理。','调解','武汉,租赁,身份材料,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_47b6268f','（2024）鄂0106民初22233号','积玉桥和园书面附件合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-09-21','承租人陈某、出租人吴某','积玉桥和园书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约23780元。','承租人陈入住积玉桥和园后主张双方对坡道维修和清洁费口头承诺发生争议，积玉桥和园交接过程中，中介未能提供完整的服务过程记录，双方遂对通知时间和费用范围产生分歧。','法院针对积玉桥和园审查了合同草案和录音摘要，这些材料能够证明交易经过，结合双方履行顺序，可认定能够写入附件的关键事项应以书面约定为主要依据，未被其他证据支持的口头说法不作为主要依据。','裁判要点是能够写入附件的关键事项应以书面约定为主要依据，在积玉桥和园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','积玉桥和园书面附件事项最终按“依有效书面条款确定责任”执行，经核算，支持金额为8746元，超出证据范围的部分不予支持。','调解','武汉,租赁,书面附件,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_a00eba6b','（2025）鄂01民初26818号','积玉桥清庭噪音减租合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-08-14','承租人唐某、出租人蒋某','积玉桥清庭噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约11335元。','积玉桥清庭的租赁关系建立后出现“长期施工噪音超过合理生活容忍范围”问题，承租人在发现问题后及时发送书面通知，承租人与出租人随后就书面附件和实际损失各自举证。','审理积玉桥清庭噪音减租争议时，合议庭先核对施工通知和连续录音记录，再比对合同附件和通知记录，根据现有证据，出租人明知重大影响仍未披露时应承担责任，责任应按实际影响划分。','法院在积玉桥清庭案件中明确出租人明知重大影响仍未披露时应承担责任，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对积玉桥清庭作出处理：酌情减免受影响期间租金，已查明损失按3697元计入责任，其余由双方依合同继续履行。','调解','武汉,租赁,噪音减租,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_3c208338','（2025）鄂0102民初20019号','水果湖公寓押金返还合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2025-05-19','承租人罗某、出租人叶某','水果湖公寓押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约11336元。','围绕水果湖公寓房屋，双方确认发生过出租人以深度保洁为由扣留押金，由于中介未能提供完整的服务过程记录，押金、维修或服务费用的承担方式未能协商一致。','水果湖公寓案卷中的转账记录和交接照片与时间记录可以相互印证，法院据此认为正常使用痕迹不能当然认定为损坏，并对双方未写入合同的承诺从严审查。','水果湖公寓案确认：正常使用痕迹不能当然认定为损坏，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就水果湖公寓争议，法院判令返还未证明损失部分的押金，凭证支持的金额核定为4147元，其余请求分别处理。','调解','武汉,租赁,押金返还,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_81ea7a2d','（2024）鄂0111民初17314号','水果湖家园维修责任合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-04-15','承租人许某、出租人沈某','水果湖家园维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约3121元。','本案源于水果湖家园交付后的维修责任事项，承租人提交材料称卫生间渗水后双方对维修期限产生分歧，出租人则以“双方曾通过物业协调但未达成一致”解释其处理过程。','对于水果湖家园发生的维修责任问题，法院以报修工单和现场检测报告为核心判断材料，综合交付状态和后续补救情况，出租人知悉后未及时维修应承担相应责任。','裁判要点是出租人知悉后未及时维修应承担相应责任，在水果湖家园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','水果湖家园维修责任事项最终按“承担维修费并赔偿合理损失”执行，经核算，支持金额为2966元，超出证据范围的部分不予支持。','调解','武汉,租赁,维修责任,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ecec0804','（2025）鄂0106民初3044号','水果湖里巷门宽说明合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-09-04','承租人韩某、出租人林某','水果湖里巷门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约2372元。','承租人韩入住水果湖里巷后主张中介口头承诺入口门宽但交付时测量不符，水果湖里巷交接过程中，中介未能提供完整的服务过程记录，双方遂对通知时间和费用范围产生分歧。','法院针对水果湖里巷审查了聊天记录和门宽测量照片，这些材料能够证明交易经过，结合双方履行顺序，可认定关键居住条件构成订约基础时应如实说明，未被其他证据支持的口头说法不作为主要依据。','法院在水果湖里巷案件中明确关键居住条件构成订约基础时应如实说明，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对水果湖里巷作出处理：退还服务费并调整违约责任，已查明损失按599元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,门宽说明,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8994e038','（2025）鄂01民初2246号','水果湖社区电梯停运合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-11-10','承租人吴某、出租人周某','水果湖社区电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约13342元。','水果湖社区的租赁关系建立后出现“高层住宅电梯长期停运影响正常使用”问题，承租人在发现问题后及时发送书面通知，承租人与出租人随后就书面附件和实际损失各自举证。','审理水果湖社区电梯停运争议时，合议庭先核对物业公告和维保记录，再比对合同附件和通知记录，根据现有证据，持续停运达到影响居住程度时可酌情减租，责任应按实际影响划分。','水果湖社区案确认：持续停运达到影响居住程度时可酌情减租，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就水果湖社区争议，法院判令按影响期间减免部分租金，凭证支持的金额核定为8561元，其余请求分别处理。','支持','武汉,租赁,电梯停运,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_056e0e2a','（2024）鄂0102民初5808号','水果湖新苑通道占用合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2024-07-17','承租人蒋某、出租人顾某','水果湖新苑通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约26733元。','围绕水果湖新苑房屋，双方确认发生过公共坡道被电动车和杂物反复占用，由于承租人在发现问题后及时发送书面通知，押金、维修或服务费用的承担方式未能协商一致。','水果湖新苑案卷中的现场视频和物业投诉记录与时间记录可以相互印证，法院据此认为管理方接报后应采取合理清理措施，并对双方未写入合同的承诺从严审查。','裁判要点是管理方接报后应采取合理清理措施，在水果湖新苑租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','水果湖新苑通道占用事项最终按“限期清理并完善巡查”执行，经核算，支持金额为24575元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,通道占用,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_29af849f','（2025）鄂0111民初13723号','水果湖华庭中介服务费合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-03-12','承租人叶某、出租人陈某','水果湖华庭中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约16024元。','本案源于水果湖华庭交付后的中介服务费事项，承租人提交材料称签约未成后中介收取全部服务费，出租人则以“承租人在发现问题后及时发送书面通知”解释其处理过程。','对于水果湖华庭发生的中介服务费问题，法院以服务协议和带看记录为核心判断材料，综合交付状态和后续补救情况，服务未完整履行时应结合实际工作量确定费用。','法院在水果湖华庭案件中明确服务未完整履行时应结合实际工作量确定费用，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对水果湖华庭作出处理：退还未实际发生的服务费，已查明损失按15298元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,中介服务费,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_9b5571b6','（2025）鄂0106民初26635号','水果湖街区提前退租合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-01-28','承租人沈某、出租人唐某','水果湖街区提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约21023元。','承租人沈入住水果湖街区后主张承租人因居住条件变化要求提前解除，水果湖街区交接过程中，出租人提交了维修报价和付款凭证，双方遂对通知时间和费用范围产生分歧。','法院针对水果湖街区审查了合同附件和沟通邮件，这些材料能够证明交易经过，结合双方履行顺序，可认定违约金过高且损失有限时可依法调整，未被其他证据支持的口头说法不作为主要依据。','水果湖街区案确认：违约金过高且损失有限时可依法调整，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就水果湖街区争议，法院判令按实际损失承担适当责任，凭证支持的金额核定为502元，其余请求分别处理。','支持','武汉,租赁,提前退租,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_89a110f8','（2025）鄂01民初23731号','水果湖邻里身份材料合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-01-02','承租人林某、出租人罗某','水果湖邻里身份材料纠纷：中介在签约前索取过多证件照片，争议金额约21990元。','水果湖邻里的租赁关系建立后出现“中介在签约前索取过多证件照片”问题，双方曾通过物业协调但未达成一致，承租人与出租人随后就书面附件和实际损失各自举证。','审理水果湖邻里身份材料争议时，合议庭先核对信息收集页面和聊天记录，再比对合同附件和通知记录，根据现有证据，租赁核验应遵循目的明确和最小必要原则，责任应按实际影响划分。','裁判要点是租赁核验应遵循目的明确和最小必要原则，在水果湖邻里租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','水果湖邻里身份材料事项最终按“删除无关材料并停止继续处理”执行，经核算，支持金额为9323元，超出证据范围的部分不予支持。','支持','武汉,租赁,身份材料,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ee7041c2','（2023）鄂0102民初12403号','水果湖小院书面附件合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-03-08','承租人周某、出租人许某','水果湖小院书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约33121元。','围绕水果湖小院房屋，双方确认发生过双方对坡道维修和清洁费口头承诺发生争议，由于双方曾通过物业协调但未达成一致，押金、维修或服务费用的承担方式未能协商一致。','水果湖小院案卷中的合同草案和录音摘要与时间记录可以相互印证，法院据此认为能够写入附件的关键事项应以书面约定为主要依据，并对双方未写入合同的承诺从严审查。','法院在水果湖小院案件中明确能够写入附件的关键事项应以书面约定为主要依据，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对水果湖小院作出处理：依有效书面条款确定责任，已查明损失按17751元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,书面附件,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_d5794d01','（2024）鄂0111民初8358号','水果湖住区噪音减租合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-06-01','承租人顾某、出租人韩某','水果湖住区噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约15132元。','本案源于水果湖住区交付后的噪音减租事项，承租人提交材料称长期施工噪音超过合理生活容忍范围，出租人则以“中介未能提供完整的服务过程记录”解释其处理过程。','对于水果湖住区发生的噪音减租问题，法院以施工通知和连续录音记录为核心判断材料，综合交付状态和后续补救情况，出租人明知重大影响仍未披露时应承担责任。','水果湖住区案确认：出租人明知重大影响仍未披露时应承担责任，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就水果湖住区争议，法院判令酌情减免受影响期间租金，凭证支持的金额核定为2052元，其余请求分别处理。','支持','武汉,租赁,噪音减租,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_6a4925e6','（2024）鄂0106民初19988号','水果湖宿舍押金返还合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-09-18','承租人陈某、出租人吴某','水果湖宿舍押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约17623元。','承租人陈入住水果湖宿舍后主张出租人以深度保洁为由扣留押金，水果湖宿舍交接过程中，中介未能提供完整的服务过程记录，双方遂对通知时间和费用范围产生分歧。','法院针对水果湖宿舍审查了转账记录和交接照片，这些材料能够证明交易经过，结合双方履行顺序，可认定正常使用痕迹不能当然认定为损坏，未被其他证据支持的口头说法不作为主要依据。','裁判要点是正常使用痕迹不能当然认定为损坏，在水果湖宿舍租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','水果湖宿舍押金返还事项最终按“返还未证明损失部分的押金”执行，经核算，支持金额为13692元，超出证据范围的部分不予支持。','驳回','武汉,租赁,押金返还,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_287fbef3','（2024）鄂01民初9079号','水果湖雅庭维修责任合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-03-25','承租人唐某、出租人蒋某','水果湖雅庭维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约18645元。','水果湖雅庭的租赁关系建立后出现“卫生间渗水后双方对维修期限产生分歧”问题，出租人提交了维修报价和付款凭证，承租人与出租人随后就书面附件和实际损失各自举证。','审理水果湖雅庭维修责任争议时，合议庭先核对报修工单和现场检测报告，再比对合同附件和通知记录，根据现有证据，出租人知悉后未及时维修应承担相应责任，责任应按实际影响划分。','法院在水果湖雅庭案件中明确出租人知悉后未及时维修应承担相应责任，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对水果湖雅庭作出处理：承担维修费并赔偿合理损失，已查明损失按12017元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,维修责任,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_79f8bb8a','（2024）鄂0102民初4016号','水果湖春晓门宽说明合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2024-05-27','承租人罗某、出租人叶某','水果湖春晓门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约23530元。','围绕水果湖春晓房屋，双方确认发生过中介口头承诺入口门宽但交付时测量不符，由于房屋交接表未记载争议项目，押金、维修或服务费用的承担方式未能协商一致。','水果湖春晓案卷中的聊天记录和门宽测量照片与时间记录可以相互印证，法院据此认为关键居住条件构成订约基础时应如实说明，并对双方未写入合同的承诺从严审查。','水果湖春晓案确认：关键居住条件构成订约基础时应如实说明，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就水果湖春晓争议，法院判令退还服务费并调整违约责任，凭证支持的金额核定为13172元，其余请求分别处理。','驳回','武汉,租赁,门宽说明,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_269a9bc8','（2023）鄂0111民初18565号','水果湖和园电梯停运合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2023-01-01','承租人许某、出租人沈某','水果湖和园电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约27626元。','本案源于水果湖和园交付后的电梯停运事项，承租人提交材料称高层住宅电梯长期停运影响正常使用，出租人则以“双方曾通过物业协调但未达成一致”解释其处理过程。','对于水果湖和园发生的电梯停运问题，法院以物业公告和维保记录为核心判断材料，综合交付状态和后续补救情况，持续停运达到影响居住程度时可酌情减租。','裁判要点是持续停运达到影响居住程度时可酌情减租，在水果湖和园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','水果湖和园电梯停运事项最终按“按影响期间减免部分租金”执行，经核算，支持金额为12573元，超出证据范围的部分不予支持。','调解','武汉,租赁,电梯停运,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_53f0a74d','（2025）鄂0106民初25322号','水果湖清庭通道占用合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-09-09','承租人韩某、出租人林某','水果湖清庭通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约3429元。','承租人韩入住水果湖清庭后主张公共坡道被电动车和杂物反复占用，水果湖清庭交接过程中，承租人在发现问题后及时发送书面通知，双方遂对通知时间和费用范围产生分歧。','法院针对水果湖清庭审查了现场视频和物业投诉记录，这些材料能够证明交易经过，结合双方履行顺序，可认定管理方接报后应采取合理清理措施，未被其他证据支持的口头说法不作为主要依据。','法院在水果湖清庭案件中明确管理方接报后应采取合理清理措施，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对水果湖清庭作出处理：限期清理并完善巡查，已查明损失按1750元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,通道占用,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_4a7ae717','（2024）鄂01民初26912号','琴台公寓中介服务费合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-02-11','承租人吴某、出租人周某','琴台公寓中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约19008元。','琴台公寓的租赁关系建立后出现“签约未成后中介收取全部服务费”问题，双方曾通过物业协调但未达成一致，承租人与出租人随后就书面附件和实际损失各自举证。','审理琴台公寓中介服务费争议时，合议庭先核对服务协议和带看记录，再比对合同附件和通知记录，根据现有证据，服务未完整履行时应结合实际工作量确定费用，责任应按实际影响划分。','琴台公寓案确认：服务未完整履行时应结合实际工作量确定费用，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就琴台公寓争议，法院判令退还未实际发生的服务费，凭证支持的金额核定为8196元，其余请求分别处理。','驳回','武汉,租赁,中介服务费,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1a7c2fe3','（2023）鄂0102民初11165号','琴台家园提前退租合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-06-21','承租人蒋某、出租人顾某','琴台家园提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约3822元。','围绕琴台家园房屋，双方确认发生过承租人因居住条件变化要求提前解除，由于双方曾通过物业协调但未达成一致，押金、维修或服务费用的承担方式未能协商一致。','琴台家园案卷中的合同附件和沟通邮件与时间记录可以相互印证，法院据此认为违约金过高且损失有限时可依法调整，并对双方未写入合同的承诺从严审查。','裁判要点是违约金过高且损失有限时可依法调整，在琴台家园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','琴台家园提前退租事项最终按“按实际损失承担适当责任”执行，经核算，支持金额为2734元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,提前退租,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_f332668b','（2024）鄂0111民初22240号','琴台里巷身份材料合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-12-22','承租人叶某、出租人陈某','琴台里巷身份材料纠纷：中介在签约前索取过多证件照片，争议金额约23643元。','本案源于琴台里巷交付后的身份材料事项，承租人提交材料称中介在签约前索取过多证件照片，出租人则以“中介未能提供完整的服务过程记录”解释其处理过程。','对于琴台里巷发生的身份材料问题，法院以信息收集页面和聊天记录为核心判断材料，综合交付状态和后续补救情况，租赁核验应遵循目的明确和最小必要原则。','法院在琴台里巷案件中明确租赁核验应遵循目的明确和最小必要原则，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对琴台里巷作出处理：删除无关材料并停止继续处理，已查明损失按18659元计入责任，其余由双方依合同继续履行。','调解','武汉,租赁,身份材料,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_96dda2b6','（2023）鄂0106民初20770号','琴台社区书面附件合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-04-05','承租人沈某、出租人唐某','琴台社区书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约10883元。','承租人沈入住琴台社区后主张双方对坡道维修和清洁费口头承诺发生争议，琴台社区交接过程中，中介未能提供完整的服务过程记录，双方遂对通知时间和费用范围产生分歧。','法院针对琴台社区审查了合同草案和录音摘要，这些材料能够证明交易经过，结合双方履行顺序，可认定能够写入附件的关键事项应以书面约定为主要依据，未被其他证据支持的口头说法不作为主要依据。','琴台社区案确认：能够写入附件的关键事项应以书面约定为主要依据，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就琴台社区争议，法院判令依有效书面条款确定责任，凭证支持的金额核定为3998元，其余请求分别处理。','驳回','武汉,租赁,书面附件,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_3949b5f8','（2024）鄂01民初25477号','琴台新苑噪音减租合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-12-04','承租人林某、出租人罗某','琴台新苑噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约7385元。','琴台新苑的租赁关系建立后出现“长期施工噪音超过合理生活容忍范围”问题，房屋交接表未记载争议项目，承租人与出租人随后就书面附件和实际损失各自举证。','审理琴台新苑噪音减租争议时，合议庭先核对施工通知和连续录音记录，再比对合同附件和通知记录，根据现有证据，出租人明知重大影响仍未披露时应承担责任，责任应按实际影响划分。','裁判要点是出租人明知重大影响仍未披露时应承担责任，在琴台新苑租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','琴台新苑噪音减租事项最终按“酌情减免受影响期间租金”执行，经核算，支持金额为2607元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,噪音减租,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_2b8174ae','（2023）鄂0102民初15618号','琴台华庭押金返还合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-01-23','承租人周某、出租人许某','琴台华庭押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约22930元。','围绕琴台华庭房屋，双方确认发生过出租人以深度保洁为由扣留押金，由于双方曾通过物业协调但未达成一致，押金、维修或服务费用的承担方式未能协商一致。','琴台华庭案卷中的转账记录和交接照片与时间记录可以相互印证，法院据此认为正常使用痕迹不能当然认定为损坏，并对双方未写入合同的承诺从严审查。','法院在琴台华庭案件中明确正常使用痕迹不能当然认定为损坏，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对琴台华庭作出处理：返还未证明损失部分的押金，已查明损失按1210元计入责任，其余由双方依合同继续履行。','调解','武汉,租赁,押金返还,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8a467436','（2025）鄂0111民初26593号','琴台街区维修责任合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-02-07','承租人顾某、出租人韩某','琴台街区维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约12226元。','本案源于琴台街区交付后的维修责任事项，承租人提交材料称卫生间渗水后双方对维修期限产生分歧，出租人则以“承租人在发现问题后及时发送书面通知”解释其处理过程。','对于琴台街区发生的维修责任问题，法院以报修工单和现场检测报告为核心判断材料，综合交付状态和后续补救情况，出租人知悉后未及时维修应承担相应责任。','琴台街区案确认：出租人知悉后未及时维修应承担相应责任，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就琴台街区争议，法院判令承担维修费并赔偿合理损失，凭证支持的金额核定为1365元，其余请求分别处理。','部分支持','武汉,租赁,维修责任,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_f7af9c74','（2025）鄂0106民初2253号','琴台邻里门宽说明合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-08-05','承租人陈某、出租人吴某','琴台邻里门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约19260元。','承租人陈入住琴台邻里后主张中介口头承诺入口门宽但交付时测量不符，琴台邻里交接过程中，双方曾通过物业协调但未达成一致，双方遂对通知时间和费用范围产生分歧。','法院针对琴台邻里审查了聊天记录和门宽测量照片，这些材料能够证明交易经过，结合双方履行顺序，可认定关键居住条件构成订约基础时应如实说明，未被其他证据支持的口头说法不作为主要依据。','裁判要点是关键居住条件构成订约基础时应如实说明，在琴台邻里租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','琴台邻里门宽说明事项最终按“退还服务费并调整违约责任”执行，经核算，支持金额为703元，超出证据范围的部分不予支持。','调解','武汉,租赁,门宽说明,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_7af1c245','（2025）鄂01民初19788号','琴台小院电梯停运合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-04-01','承租人唐某、出租人蒋某','琴台小院电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约28209元。','琴台小院的租赁关系建立后出现“高层住宅电梯长期停运影响正常使用”问题，中介未能提供完整的服务过程记录，承租人与出租人随后就书面附件和实际损失各自举证。','审理琴台小院电梯停运争议时，合议庭先核对物业公告和维保记录，再比对合同附件和通知记录，根据现有证据，持续停运达到影响居住程度时可酌情减租，责任应按实际影响划分。','法院在琴台小院案件中明确持续停运达到影响居住程度时可酌情减租，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对琴台小院作出处理：按影响期间减免部分租金，已查明损失按5132元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,电梯停运,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_2caa4d1a','（2024）鄂0102民初13396号','琴台住区通道占用合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2024-12-24','承租人罗某、出租人叶某','琴台住区通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约5450元。','围绕琴台住区房屋，双方确认发生过公共坡道被电动车和杂物反复占用，由于中介未能提供完整的服务过程记录，押金、维修或服务费用的承担方式未能协商一致。','琴台住区案卷中的现场视频和物业投诉记录与时间记录可以相互印证，法院据此认为管理方接报后应采取合理清理措施，并对双方未写入合同的承诺从严审查。','琴台住区案确认：管理方接报后应采取合理清理措施，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就琴台住区争议，法院判令限期清理并完善巡查，凭证支持的金额核定为4468元，其余请求分别处理。','驳回','武汉,租赁,通道占用,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ddbfe89c','（2025）鄂0111民初9079号','琴台宿舍中介服务费合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-01-02','承租人许某、出租人沈某','琴台宿舍中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约15999元。','本案源于琴台宿舍交付后的中介服务费事项，承租人提交材料称签约未成后中介收取全部服务费，出租人则以“承租人在发现问题后及时发送书面通知”解释其处理过程。','对于琴台宿舍发生的中介服务费问题，法院以服务协议和带看记录为核心判断材料，综合交付状态和后续补救情况，服务未完整履行时应结合实际工作量确定费用。','裁判要点是服务未完整履行时应结合实际工作量确定费用，在琴台宿舍租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','琴台宿舍中介服务费事项最终按“退还未实际发生的服务费”执行，经核算，支持金额为8018元，超出证据范围的部分不予支持。','调解','武汉,租赁,中介服务费,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_62e7c551','（2024）鄂0106民初14158号','琴台雅庭提前退租合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-11-25','承租人韩某、出租人林某','琴台雅庭提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约25553元。','承租人韩入住琴台雅庭后主张承租人因居住条件变化要求提前解除，琴台雅庭交接过程中，中介未能提供完整的服务过程记录，双方遂对通知时间和费用范围产生分歧。','法院针对琴台雅庭审查了合同附件和沟通邮件，这些材料能够证明交易经过，结合双方履行顺序，可认定违约金过高且损失有限时可依法调整，未被其他证据支持的口头说法不作为主要依据。','法院在琴台雅庭案件中明确违约金过高且损失有限时可依法调整，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对琴台雅庭作出处理：按实际损失承担适当责任，已查明损失按13965元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,提前退租,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_27169220','（2024）鄂01民初23338号','琴台春晓身份材料合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-11-17','承租人吴某、出租人周某','琴台春晓身份材料纠纷：中介在签约前索取过多证件照片，争议金额约35512元。','琴台春晓的租赁关系建立后出现“中介在签约前索取过多证件照片”问题，中介未能提供完整的服务过程记录，承租人与出租人随后就书面附件和实际损失各自举证。','审理琴台春晓身份材料争议时，合议庭先核对信息收集页面和聊天记录，再比对合同附件和通知记录，根据现有证据，租赁核验应遵循目的明确和最小必要原则，责任应按实际影响划分。','琴台春晓案确认：租赁核验应遵循目的明确和最小必要原则，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就琴台春晓争议，法院判令删除无关材料并停止继续处理，凭证支持的金额核定为14907元，其余请求分别处理。','支持','武汉,租赁,身份材料,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e4d842fe','（2025）鄂0102民初3746号','琴台和园书面附件合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2025-11-13','承租人蒋某、出租人顾某','琴台和园书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约2052元。','围绕琴台和园房屋，双方确认发生过双方对坡道维修和清洁费口头承诺发生争议，由于房屋交接表未记载争议项目，押金、维修或服务费用的承担方式未能协商一致。','琴台和园案卷中的合同草案和录音摘要与时间记录可以相互印证，法院据此认为能够写入附件的关键事项应以书面约定为主要依据，并对双方未写入合同的承诺从严审查。','裁判要点是能够写入附件的关键事项应以书面约定为主要依据，在琴台和园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','琴台和园书面附件事项最终按“依有效书面条款确定责任”执行，经核算，支持金额为1433元，超出证据范围的部分不予支持。','支持','武汉,租赁,书面附件,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_33581e25','（2025）鄂0111民初28917号','琴台清庭噪音减租合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-10-28','承租人叶某、出租人陈某','琴台清庭噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约5132元。','本案源于琴台清庭交付后的噪音减租事项，承租人提交材料称长期施工噪音超过合理生活容忍范围，出租人则以“房屋交接表未记载争议项目”解释其处理过程。','对于琴台清庭发生的噪音减租问题，法院以施工通知和连续录音记录为核心判断材料，综合交付状态和后续补救情况，出租人明知重大影响仍未披露时应承担责任。','法院在琴台清庭案件中明确出租人明知重大影响仍未披露时应承担责任，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对琴台清庭作出处理：酌情减免受影响期间租金，已查明损失按982元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,噪音减租,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_9f3b8033','（2023）鄂0106民初5521号','墨水湖公寓押金返还合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-11-14','承租人沈某、出租人唐某','墨水湖公寓押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约33194元。','承租人沈入住墨水湖公寓后主张出租人以深度保洁为由扣留押金，墨水湖公寓交接过程中，房屋交接表未记载争议项目，双方遂对通知时间和费用范围产生分歧。','法院针对墨水湖公寓审查了转账记录和交接照片，这些材料能够证明交易经过，结合双方履行顺序，可认定正常使用痕迹不能当然认定为损坏，未被其他证据支持的口头说法不作为主要依据。','墨水湖公寓案确认：正常使用痕迹不能当然认定为损坏，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就墨水湖公寓争议，法院判令返还未证明损失部分的押金，凭证支持的金额核定为18368元，其余请求分别处理。','驳回','武汉,租赁,押金返还,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_3828b316','（2025）鄂01民初26969号','墨水湖家园维修责任合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-11-28','承租人林某、出租人罗某','墨水湖家园维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约27436元。','墨水湖家园的租赁关系建立后出现“卫生间渗水后双方对维修期限产生分歧”问题，承租人在发现问题后及时发送书面通知，承租人与出租人随后就书面附件和实际损失各自举证。','审理墨水湖家园维修责任争议时，合议庭先核对报修工单和现场检测报告，再比对合同附件和通知记录，根据现有证据，出租人知悉后未及时维修应承担相应责任，责任应按实际影响划分。','裁判要点是出租人知悉后未及时维修应承担相应责任，在墨水湖家园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','墨水湖家园维修责任事项最终按“承担维修费并赔偿合理损失”执行，经核算，支持金额为15959元，超出证据范围的部分不予支持。','调解','武汉,租赁,维修责任,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_c8108c8c','（2023）鄂0102民初16084号','墨水湖里巷门宽说明合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-05-19','承租人周某、出租人许某','墨水湖里巷门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约14872元。','围绕墨水湖里巷房屋，双方确认发生过中介口头承诺入口门宽但交付时测量不符，由于出租人提交了维修报价和付款凭证，押金、维修或服务费用的承担方式未能协商一致。','墨水湖里巷案卷中的聊天记录和门宽测量照片与时间记录可以相互印证，法院据此认为关键居住条件构成订约基础时应如实说明，并对双方未写入合同的承诺从严审查。','法院在墨水湖里巷案件中明确关键居住条件构成订约基础时应如实说明，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对墨水湖里巷作出处理：退还服务费并调整违约责任，已查明损失按10072元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,门宽说明,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_26476ac3','（2023）鄂0111民初24739号','墨水湖社区电梯停运合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2023-12-15','承租人顾某、出租人韩某','墨水湖社区电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约24685元。','本案源于墨水湖社区交付后的电梯停运事项，承租人提交材料称高层住宅电梯长期停运影响正常使用，出租人则以“出租人提交了维修报价和付款凭证”解释其处理过程。','对于墨水湖社区发生的电梯停运问题，法院以物业公告和维保记录为核心判断材料，综合交付状态和后续补救情况，持续停运达到影响居住程度时可酌情减租。','墨水湖社区案确认：持续停运达到影响居住程度时可酌情减租，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就墨水湖社区争议，法院判令按影响期间减免部分租金，凭证支持的金额核定为10496元，其余请求分别处理。','支持','武汉,租赁,电梯停运,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_86318ac6','（2023）鄂0106民初2594号','墨水湖新苑通道占用合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2023-03-18','承租人陈某、出租人吴某','墨水湖新苑通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约20125元。','承租人陈入住墨水湖新苑后主张公共坡道被电动车和杂物反复占用，墨水湖新苑交接过程中，双方曾通过物业协调但未达成一致，双方遂对通知时间和费用范围产生分歧。','法院针对墨水湖新苑审查了现场视频和物业投诉记录，这些材料能够证明交易经过，结合双方履行顺序，可认定管理方接报后应采取合理清理措施，未被其他证据支持的口头说法不作为主要依据。','裁判要点是管理方接报后应采取合理清理措施，在墨水湖新苑租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','墨水湖新苑通道占用事项最终按“限期清理并完善巡查”执行，经核算，支持金额为10483元，超出证据范围的部分不予支持。','调解','武汉,租赁,通道占用,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_304e9098','（2023）鄂01民初24275号','墨水湖华庭中介服务费合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2023-12-17','承租人唐某、出租人蒋某','墨水湖华庭中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约14283元。','墨水湖华庭的租赁关系建立后出现“签约未成后中介收取全部服务费”问题，中介未能提供完整的服务过程记录，承租人与出租人随后就书面附件和实际损失各自举证。','审理墨水湖华庭中介服务费争议时，合议庭先核对服务协议和带看记录，再比对合同附件和通知记录，根据现有证据，服务未完整履行时应结合实际工作量确定费用，责任应按实际影响划分。','法院在墨水湖华庭案件中明确服务未完整履行时应结合实际工作量确定费用，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对墨水湖华庭作出处理：退还未实际发生的服务费，已查明损失按6539元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,中介服务费,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_8f03c150','（2023）鄂0102民初6988号','墨水湖街区提前退租合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-03-05','承租人罗某、出租人叶某','墨水湖街区提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约16238元。','围绕墨水湖街区房屋，双方确认发生过承租人因居住条件变化要求提前解除，由于出租人提交了维修报价和付款凭证，押金、维修或服务费用的承担方式未能协商一致。','墨水湖街区案卷中的合同附件和沟通邮件与时间记录可以相互印证，法院据此认为违约金过高且损失有限时可依法调整，并对双方未写入合同的承诺从严审查。','墨水湖街区案确认：违约金过高且损失有限时可依法调整，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就墨水湖街区争议，法院判令按实际损失承担适当责任，凭证支持的金额核定为4090元，其余请求分别处理。','部分支持','武汉,租赁,提前退租,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_1c38f80d','（2025）鄂0111民初21634号','墨水湖邻里身份材料合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-07-11','承租人许某、出租人沈某','墨水湖邻里身份材料纠纷：中介在签约前索取过多证件照片，争议金额约18232元。','本案源于墨水湖邻里交付后的身份材料事项，承租人提交材料称中介在签约前索取过多证件照片，出租人则以“房屋交接表未记载争议项目”解释其处理过程。','对于墨水湖邻里发生的身份材料问题，法院以信息收集页面和聊天记录为核心判断材料，综合交付状态和后续补救情况，租赁核验应遵循目的明确和最小必要原则。','裁判要点是租赁核验应遵循目的明确和最小必要原则，在墨水湖邻里租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','墨水湖邻里身份材料事项最终按“删除无关材料并停止继续处理”执行，经核算，支持金额为14548元，超出证据范围的部分不予支持。','调解','武汉,租赁,身份材料,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_29b39ca4','（2024）鄂0106民初22374号','墨水湖小院书面附件合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-02-03','承租人韩某、出租人林某','墨水湖小院书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约2525元。','承租人韩入住墨水湖小院后主张双方对坡道维修和清洁费口头承诺发生争议，墨水湖小院交接过程中，双方曾通过物业协调但未达成一致，双方遂对通知时间和费用范围产生分歧。','法院针对墨水湖小院审查了合同草案和录音摘要，这些材料能够证明交易经过，结合双方履行顺序，可认定能够写入附件的关键事项应以书面约定为主要依据，未被其他证据支持的口头说法不作为主要依据。','法院在墨水湖小院案件中明确能够写入附件的关键事项应以书面约定为主要依据，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对墨水湖小院作出处理：依有效书面条款确定责任，已查明损失按872元计入责任，其余由双方依合同继续履行。','驳回','武汉,租赁,书面附件,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_73692d66','（2025）鄂01民初28343号','墨水湖住区噪音减租合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-04-12','承租人吴某、出租人周某','墨水湖住区噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约12356元。','墨水湖住区的租赁关系建立后出现“长期施工噪音超过合理生活容忍范围”问题，承租人在发现问题后及时发送书面通知，承租人与出租人随后就书面附件和实际损失各自举证。','审理墨水湖住区噪音减租争议时，合议庭先核对施工通知和连续录音记录，再比对合同附件和通知记录，根据现有证据，出租人明知重大影响仍未披露时应承担责任，责任应按实际影响划分。','墨水湖住区案确认：出租人明知重大影响仍未披露时应承担责任，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就墨水湖住区争议，法院判令酌情减免受影响期间租金，凭证支持的金额核定为9357元，其余请求分别处理。','支持','武汉,租赁,噪音减租,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_afd095c8','（2025）鄂0102民初10672号','墨水湖宿舍押金返还合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2025-06-13','承租人蒋某、出租人顾某','墨水湖宿舍押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约4100元。','围绕墨水湖宿舍房屋，双方确认发生过出租人以深度保洁为由扣留押金，由于出租人提交了维修报价和付款凭证，押金、维修或服务费用的承担方式未能协商一致。','墨水湖宿舍案卷中的转账记录和交接照片与时间记录可以相互印证，法院据此认为正常使用痕迹不能当然认定为损坏，并对双方未写入合同的承诺从严审查。','裁判要点是正常使用痕迹不能当然认定为损坏，在墨水湖宿舍租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','墨水湖宿舍押金返还事项最终按“返还未证明损失部分的押金”执行，经核算，支持金额为2163元，超出证据范围的部分不予支持。','驳回','武汉,租赁,押金返还,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_f6ec40f8','（2024）鄂0111民初10797号','墨水湖雅庭维修责任合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-12-22','承租人叶某、出租人陈某','墨水湖雅庭维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约9367元。','本案源于墨水湖雅庭交付后的维修责任事项，承租人提交材料称卫生间渗水后双方对维修期限产生分歧，出租人则以“承租人在发现问题后及时发送书面通知”解释其处理过程。','对于墨水湖雅庭发生的维修责任问题，法院以报修工单和现场检测报告为核心判断材料，综合交付状态和后续补救情况，出租人知悉后未及时维修应承担相应责任。','法院在墨水湖雅庭案件中明确出租人知悉后未及时维修应承担相应责任，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对墨水湖雅庭作出处理：承担维修费并赔偿合理损失，已查明损失按7343元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,维修责任,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_4d10820e','（2024）鄂0106民初23426号','墨水湖春晓门宽说明合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-12-26','承租人沈某、出租人唐某','墨水湖春晓门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约14475元。','承租人沈入住墨水湖春晓后主张中介口头承诺入口门宽但交付时测量不符，墨水湖春晓交接过程中，承租人在发现问题后及时发送书面通知，双方遂对通知时间和费用范围产生分歧。','法院针对墨水湖春晓审查了聊天记录和门宽测量照片，这些材料能够证明交易经过，结合双方履行顺序，可认定关键居住条件构成订约基础时应如实说明，未被其他证据支持的口头说法不作为主要依据。','墨水湖春晓案确认：关键居住条件构成订约基础时应如实说明，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就墨水湖春晓争议，法院判令退还服务费并调整违约责任，凭证支持的金额核定为2360元，其余请求分别处理。','部分支持','武汉,租赁,门宽说明,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_0e45c7ca','（2024）鄂01民初22640号','墨水湖和园电梯停运合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2024-01-26','承租人林某、出租人罗某','墨水湖和园电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约33663元。','墨水湖和园的租赁关系建立后出现“高层住宅电梯长期停运影响正常使用”问题，房屋交接表未记载争议项目，承租人与出租人随后就书面附件和实际损失各自举证。','审理墨水湖和园电梯停运争议时，合议庭先核对物业公告和维保记录，再比对合同附件和通知记录，根据现有证据，持续停运达到影响居住程度时可酌情减租，责任应按实际影响划分。','裁判要点是持续停运达到影响居住程度时可酌情减租，在墨水湖和园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','墨水湖和园电梯停运事项最终按“按影响期间减免部分租金”执行，经核算，支持金额为14366元，超出证据范围的部分不予支持。','调解','武汉,租赁,电梯停运,无障碍');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_0e698fd7','（2023）鄂0102民初17524号','墨水湖清庭通道占用合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-05-02','承租人周某、出租人许某','墨水湖清庭通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约4410元。','围绕墨水湖清庭房屋，双方确认发生过公共坡道被电动车和杂物反复占用，由于出租人提交了维修报价和付款凭证，押金、维修或服务费用的承担方式未能协商一致。','墨水湖清庭案卷中的现场视频和物业投诉记录与时间记录可以相互印证，法院据此认为管理方接报后应采取合理清理措施，并对双方未写入合同的承诺从严审查。','法院在墨水湖清庭案件中明确管理方接报后应采取合理清理措施，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对墨水湖清庭作出处理：限期清理并完善巡查，已查明损失按2640元计入责任，其余由双方依合同继续履行。','调解','武汉,租赁,通道占用,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_711c2a12','（2023）鄂0111民初27607号','青禾公寓中介服务费合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2023-11-11','承租人顾某、出租人韩某','青禾公寓中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约30413元。','本案源于青禾公寓交付后的中介服务费事项，承租人提交材料称签约未成后中介收取全部服务费，出租人则以“承租人在发现问题后及时发送书面通知”解释其处理过程。','对于青禾公寓发生的中介服务费问题，法院以服务协议和带看记录为核心判断材料，综合交付状态和后续补救情况，服务未完整履行时应结合实际工作量确定费用。','青禾公寓案确认：服务未完整履行时应结合实际工作量确定费用，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就青禾公寓争议，法院判令退还未实际发生的服务费，凭证支持的金额核定为366元，其余请求分别处理。','支持','武汉,租赁,中介服务费,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_a90db933','（2024）鄂0106民初19713号','青禾家园提前退租合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-04-13','承租人陈某、出租人吴某','青禾家园提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约29369元。','承租人陈入住青禾家园后主张承租人因居住条件变化要求提前解除，青禾家园交接过程中，出租人提交了维修报价和付款凭证，双方遂对通知时间和费用范围产生分歧。','法院针对青禾家园审查了合同附件和沟通邮件，这些材料能够证明交易经过，结合双方履行顺序，可认定违约金过高且损失有限时可依法调整，未被其他证据支持的口头说法不作为主要依据。','裁判要点是违约金过高且损失有限时可依法调整，在青禾家园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','青禾家园提前退租事项最终按“按实际损失承担适当责任”执行，经核算，支持金额为11917元，超出证据范围的部分不予支持。','支持','武汉,租赁,提前退租,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_cdc9e6bb','（2025）鄂01民初10787号','青禾里巷身份材料合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-09-18','承租人唐某、出租人蒋某','青禾里巷身份材料纠纷：中介在签约前索取过多证件照片，争议金额约3535元。','青禾里巷的租赁关系建立后出现“中介在签约前索取过多证件照片”问题，承租人在发现问题后及时发送书面通知，承租人与出租人随后就书面附件和实际损失各自举证。','审理青禾里巷身份材料争议时，合议庭先核对信息收集页面和聊天记录，再比对合同附件和通知记录，根据现有证据，租赁核验应遵循目的明确和最小必要原则，责任应按实际影响划分。','法院在青禾里巷案件中明确租赁核验应遵循目的明确和最小必要原则，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对青禾里巷作出处理：删除无关材料并停止继续处理，已查明损失按1356元计入责任，其余由双方依合同继续履行。','调解','武汉,租赁,身份材料,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_b30cfad8','（2025）鄂0102民初11567号','青禾社区书面附件合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2025-01-09','承租人罗某、出租人叶某','青禾社区书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约35703元。','围绕青禾社区房屋，双方确认发生过双方对坡道维修和清洁费口头承诺发生争议，由于双方曾通过物业协调但未达成一致，押金、维修或服务费用的承担方式未能协商一致。','青禾社区案卷中的合同草案和录音摘要与时间记录可以相互印证，法院据此认为能够写入附件的关键事项应以书面约定为主要依据，并对双方未写入合同的承诺从严审查。','青禾社区案确认：能够写入附件的关键事项应以书面约定为主要依据，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就青禾社区争议，法院判令依有效书面条款确定责任，凭证支持的金额核定为23926元，其余请求分别处理。','驳回','武汉,租赁,书面附件,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_4ff60803','（2025）鄂0111民初19177号','青禾新苑噪音减租合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-09-16','承租人许某、出租人沈某','青禾新苑噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约29920元。','本案源于青禾新苑交付后的噪音减租事项，承租人提交材料称长期施工噪音超过合理生活容忍范围，出租人则以“双方曾通过物业协调但未达成一致”解释其处理过程。','对于青禾新苑发生的噪音减租问题，法院以施工通知和连续录音记录为核心判断材料，综合交付状态和后续补救情况，出租人明知重大影响仍未披露时应承担责任。','裁判要点是出租人明知重大影响仍未披露时应承担责任，在青禾新苑租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','青禾新苑噪音减租事项最终按“酌情减免受影响期间租金”执行，经核算，支持金额为21628元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,噪音减租,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ee40b664','（2025）鄂0106民初15094号','青禾华庭押金返还合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-12-21','承租人韩某、出租人林某','青禾华庭押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约18812元。','承租人韩入住青禾华庭后主张出租人以深度保洁为由扣留押金，青禾华庭交接过程中，中介未能提供完整的服务过程记录，双方遂对通知时间和费用范围产生分歧。','法院针对青禾华庭审查了转账记录和交接照片，这些材料能够证明交易经过，结合双方履行顺序，可认定正常使用痕迹不能当然认定为损坏，未被其他证据支持的口头说法不作为主要依据。','法院在青禾华庭案件中明确正常使用痕迹不能当然认定为损坏，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对青禾华庭作出处理：返还未证明损失部分的押金，已查明损失按9563元计入责任，其余由双方依合同继续履行。','调解','武汉,租赁,押金返还,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_a1ca4cb4','（2025）鄂01民初11170号','青禾街区维修责任合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2025-01-12','承租人吴某、出租人周某','青禾街区维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约7927元。','青禾街区的租赁关系建立后出现“卫生间渗水后双方对维修期限产生分歧”问题，中介未能提供完整的服务过程记录，承租人与出租人随后就书面附件和实际损失各自举证。','审理青禾街区维修责任争议时，合议庭先核对报修工单和现场检测报告，再比对合同附件和通知记录，根据现有证据，出租人知悉后未及时维修应承担相应责任，责任应按实际影响划分。','青禾街区案确认：出租人知悉后未及时维修应承担相应责任，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就青禾街区争议，法院判令承担维修费并赔偿合理损失，凭证支持的金额核定为4099元，其余请求分别处理。','驳回','武汉,租赁,维修责任,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_54683107','（2025）鄂0102民初18640号','青禾邻里门宽说明合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2025-04-09','承租人蒋某、出租人顾某','青禾邻里门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约14092元。','围绕青禾邻里房屋，双方确认发生过中介口头承诺入口门宽但交付时测量不符，由于出租人提交了维修报价和付款凭证，押金、维修或服务费用的承担方式未能协商一致。','青禾邻里案卷中的聊天记录和门宽测量照片与时间记录可以相互印证，法院据此认为关键居住条件构成订约基础时应如实说明，并对双方未写入合同的承诺从严审查。','裁判要点是关键居住条件构成订约基础时应如实说明，在青禾邻里租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','青禾邻里门宽说明事项最终按“退还服务费并调整违约责任”执行，经核算，支持金额为7374元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,门宽说明,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e28b2b35','（2024）鄂0111民初7774号','青禾小院电梯停运合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-07-09','承租人叶某、出租人陈某','青禾小院电梯停运纠纷：高层住宅电梯长期停运影响正常使用，争议金额约20040元。','本案源于青禾小院交付后的电梯停运事项，承租人提交材料称高层住宅电梯长期停运影响正常使用，出租人则以“双方曾通过物业协调但未达成一致”解释其处理过程。','对于青禾小院发生的电梯停运问题，法院以物业公告和维保记录为核心判断材料，综合交付状态和后续补救情况，持续停运达到影响居住程度时可酌情减租。','法院在青禾小院案件中明确持续停运达到影响居住程度时可酌情减租，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对青禾小院作出处理：按影响期间减免部分租金，已查明损失按18062元计入责任，其余由双方依合同继续履行。','支持','武汉,租赁,电梯停运,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_4ddaa053','（2024）鄂0106民初7424号','青禾住区通道占用合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-11-27','承租人沈某、出租人唐某','青禾住区通道占用纠纷：公共坡道被电动车和杂物反复占用，争议金额约10258元。','承租人沈入住青禾住区后主张公共坡道被电动车和杂物反复占用，青禾住区交接过程中，出租人提交了维修报价和付款凭证，双方遂对通知时间和费用范围产生分歧。','法院针对青禾住区审查了现场视频和物业投诉记录，这些材料能够证明交易经过，结合双方履行顺序，可认定管理方接报后应采取合理清理措施，未被其他证据支持的口头说法不作为主要依据。','青禾住区案确认：管理方接报后应采取合理清理措施，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就青禾住区争议，法院判令限期清理并完善巡查，凭证支持的金额核定为5542元，其余请求分别处理。','部分支持','武汉,租赁,通道占用,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_d75add1d','（2023）鄂01民初14718号','青禾宿舍中介服务费合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2023-05-09','承租人林某、出租人罗某','青禾宿舍中介服务费纠纷：签约未成后中介收取全部服务费，争议金额约5071元。','青禾宿舍的租赁关系建立后出现“签约未成后中介收取全部服务费”问题，中介未能提供完整的服务过程记录，承租人与出租人随后就书面附件和实际损失各自举证。','审理青禾宿舍中介服务费争议时，合议庭先核对服务协议和带看记录，再比对合同附件和通知记录，根据现有证据，服务未完整履行时应结合实际工作量确定费用，责任应按实际影响划分。','裁判要点是服务未完整履行时应结合实际工作量确定费用，在青禾宿舍租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','青禾宿舍中介服务费事项最终按“退还未实际发生的服务费”执行，经核算，支持金额为4245元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,中介服务费,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_e93d4ae4','（2025）鄂0102民初22419号','青禾雅庭提前退租合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2025-07-04','承租人周某、出租人许某','青禾雅庭提前退租纠纷：承租人因居住条件变化要求提前解除，争议金额约35134元。','围绕青禾雅庭房屋，双方确认发生过承租人因居住条件变化要求提前解除，由于承租人在发现问题后及时发送书面通知，押金、维修或服务费用的承担方式未能协商一致。','青禾雅庭案卷中的合同附件和沟通邮件与时间记录可以相互印证，法院据此认为违约金过高且损失有限时可依法调整，并对双方未写入合同的承诺从严审查。','法院在青禾雅庭案件中明确违约金过高且损失有限时可依法调整，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对青禾雅庭作出处理：按实际损失承担适当责任，已查明损失按13425元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,提前退租,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_099cb7fd','（2025）鄂0111民初13934号','青禾春晓身份材料合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2025-02-07','承租人顾某、出租人韩某','青禾春晓身份材料纠纷：中介在签约前索取过多证件照片，争议金额约28175元。','本案源于青禾春晓交付后的身份材料事项，承租人提交材料称中介在签约前索取过多证件照片，出租人则以“中介未能提供完整的服务过程记录”解释其处理过程。','对于青禾春晓发生的身份材料问题，法院以信息收集页面和聊天记录为核心判断材料，综合交付状态和后续补救情况，租赁核验应遵循目的明确和最小必要原则。','青禾春晓案确认：租赁核验应遵循目的明确和最小必要原则，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就青禾春晓争议，法院判令删除无关材料并停止继续处理，凭证支持的金额核定为3082元，其余请求分别处理。','调解','武汉,租赁,身份材料,服务费');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_aafd3aec','（2024）鄂0106民初2047号','青禾和园书面附件合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2024-07-24','承租人陈某、出租人吴某','青禾和园书面附件纠纷：双方对坡道维修和清洁费口头承诺发生争议，争议金额约8464元。','承租人陈入住青禾和园后主张双方对坡道维修和清洁费口头承诺发生争议，青禾和园交接过程中，双方曾通过物业协调但未达成一致，双方遂对通知时间和费用范围产生分歧。','法院针对青禾和园审查了合同草案和录音摘要，这些材料能够证明交易经过，结合双方履行顺序，可认定能够写入附件的关键事项应以书面约定为主要依据，未被其他证据支持的口头说法不作为主要依据。','裁判要点是能够写入附件的关键事项应以书面约定为主要依据，在青禾和园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','青禾和园书面附件事项最终按“依有效书面条款确定责任”执行，经核算，支持金额为5824元，超出证据范围的部分不予支持。','调解','武汉,租赁,书面附件,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_3522d36f','（2023）鄂01民初20859号','青禾清庭噪音减租合同纠纷案','court_wh_intermediate','合同纠纷','房屋租赁合同纠纷','2023-05-25','承租人唐某、出租人蒋某','青禾清庭噪音减租纠纷：长期施工噪音超过合理生活容忍范围，争议金额约23112元。','青禾清庭的租赁关系建立后出现“长期施工噪音超过合理生活容忍范围”问题，房屋交接表未记载争议项目，承租人与出租人随后就书面附件和实际损失各自举证。','审理青禾清庭噪音减租争议时，合议庭先核对施工通知和连续录音记录，再比对合同附件和通知记录，根据现有证据，出租人明知重大影响仍未披露时应承担责任，责任应按实际影响划分。','法院在青禾清庭案件中明确出租人明知重大影响仍未披露时应承担责任，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对青禾清庭作出处理：酌情减免受影响期间租金，已查明损失按4559元计入责任，其余由双方依合同继续履行。','调解','武汉,租赁,噪音减租,押金');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_ca2e6a4b','（2023）鄂0102民初22397号','光谷公寓押金返还合同纠纷案','court_wh_jiangan','合同纠纷','房屋租赁合同纠纷','2023-09-04','承租人罗某、出租人叶某','光谷公寓押金返还纠纷：出租人以深度保洁为由扣留押金，争议金额约9686元。','围绕光谷公寓房屋，双方确认发生过出租人以深度保洁为由扣留押金，由于中介未能提供完整的服务过程记录，押金、维修或服务费用的承担方式未能协商一致。','光谷公寓案卷中的转账记录和交接照片与时间记录可以相互印证，法院据此认为正常使用痕迹不能当然认定为损坏，并对双方未写入合同的承诺从严审查。','光谷公寓案确认：正常使用痕迹不能当然认定为损坏，其中涉及的门宽、维修和服务费均应回到具体书面证据判断。','就光谷公寓争议，法院判令返还未证明损失部分的押金，凭证支持的金额核定为7324元，其余请求分别处理。','调解','武汉,租赁,押金返还,门宽');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_93b2bb24','（2024）鄂0111民初4438号','光谷家园维修责任合同纠纷案','court_wh_hongshan','合同纠纷','房屋租赁合同纠纷','2024-11-12','承租人许某、出租人沈某','光谷家园维修责任纠纷：卫生间渗水后双方对维修期限产生分歧，争议金额约12942元。','本案源于光谷家园交付后的维修责任事项，承租人提交材料称卫生间渗水后双方对维修期限产生分歧，出租人则以“双方曾通过物业协调但未达成一致”解释其处理过程。','对于光谷家园发生的维修责任问题，法院以报修工单和现场检测报告为核心判断材料，综合交付状态和后续补救情况，出租人知悉后未及时维修应承担相应责任。','裁判要点是出租人知悉后未及时维修应承担相应责任，在光谷家园租赁中，押金、无障碍设施和维修期限不能只依赖口头表述。','光谷家园维修责任事项最终按“承担维修费并赔偿合理损失”执行，经核算，支持金额为1533元，超出证据范围的部分不予支持。','部分支持','武汉,租赁,维修责任,维修');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_wh_bb7299ea','（2025）鄂0106民初22997号','光谷里巷门宽说明合同纠纷案','court_wh_wuchang','合同纠纷','房屋租赁合同纠纷','2025-06-18','承租人韩某、出租人林某','光谷里巷门宽说明纠纷：中介口头承诺入口门宽但交付时测量不符，争议金额约23787元。','承租人韩入住光谷里巷后主张中介口头承诺入口门宽但交付时测量不符，光谷里巷交接过程中，承租人在发现问题后及时发送书面通知，双方遂对通知时间和费用范围产生分歧。','法院针对光谷里巷审查了聊天记录和门宽测量照片，这些材料能够证明交易经过，结合双方履行顺序，可认定关键居住条件构成订约基础时应如实说明，未被其他证据支持的口头说法不作为主要依据。','法院在光谷里巷案件中明确关键居住条件构成订约基础时应如实说明，关键费用和居住条件应通过合同附件、交接表或通知记录固定。','法院对光谷里巷作出处理：退还服务费并调整违约责任，已查明损失按3082元计入责任，其余由双方依合同继续履行。','部分支持','武汉,租赁,门宽说明,无障碍');
